const jalaliParts=(date)=>{const d=new Date(date+'T12:00:00');const parts=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'numeric',day:'numeric'}).formatToParts(d);const find=t=>Number(parts.find(x=>x.type===t)?.value);return {year:find('year'),month:find('month'),day:find('day')}};
