const fmtDate=(date)=>{if(!date)return '—';const d=new Date(date+'T12:00:00');return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat(locale()==='en'?'en-GB':'fa-IR-u-ca-persian',{year:'numeric',month:'long',day:'numeric'}).format(d)};
/* Persian check-date picker. Financial records continue to use ISO Gregorian days internally. */
const CHECK_JALALI_WEEKDAYS=['ش','ی','د','س','چ','پ','ج'];
const checkPad=n=>String(n).padStart(2,'0');
const checkText=(fa,en)=>locale()==='en'?en:fa;
