const state={data:null,workspace:'personal',page:'dashboard',filter:{q:'',type:'all',account:'all',from:'',to:''},reportMonth:monthNow(),debtFilter:'all',checkFilter:'all',reminderAll:false,locked:false,pinAttempts:0,pinBlockedUntil:0,backgroundAt:0,checkImagesRemoved:{front:false,back:false},guideQuery:'',guideGroup:'all',tourActive:false,tourStep:-1,menu:false,modal:null,receiptRemoved:false,storageError:false};
let idb, saveQueue=Promise.resolve();
function dbOpen(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(STORE))req.result.createObjectStore(STORE)};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function dbGet(){return new Promise((resolve,reject)=>{const r=idb.transaction(STORE,'readonly').objectStore(STORE).get(KEY);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbSet(value){return new Promise((resolve,reject)=>{const tx=idb.transaction(STORE,'readwrite');tx.objectStore(STORE).put(value,KEY);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function persist(){const snapshot=JSON.parse(JSON.stringify(state.data));saveQueue=saveQueue.catch(()=>{}).then(()=>dbSet(snapshot));try{await saveQueue;state.storageError=false}catch(e){state.storageError=true;console.error(e);throw new Error('ذخیره انجام نشد؛ فضای ذخیره‌سازی یا مجوز مرورگر را بررسی کن.')}}
const ask=msg=>window.confirm(locale()==='en'?(window.HY_I18N?.translate(msg)||msg):msg);
const ws=()=>state.data.workspaces[state.workspace];
const allAccounts=()=>ws().accounts;
const findAccount=id=>ws().accounts.find(a=>a.id===id);
const accountName=id=>findAccount(id)?.name||'حساب حذف‌شده';
const remaining=d=>Math.max(0,Number((d.amount-(d.settlements||[]).reduce((sum,s)=>sum+Number(s.amount),0)).toFixed(4)));
const debtPaid=d=>(d.settlements||[]).reduce((sum,s)=>sum+Number(s.amount),0);
const isISODate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d)&&!Number.isNaN(new Date(d+'T12:00:00').getTime());
const addMonths=(date,n=1)=>{const [y,m,d]=date.split('-').map(Number);const yr=y+Math.floor((m-1+n)/12),mo=((m-1+n)%12+12)%12+1;const last=new Date(yr,mo,0).getDate();return `${yr}-${String(mo).padStart(2,'0')}-${String(Math.min(d,last)).padStart(2,'0')}`;};
const roundCur=(x,cur)=>Number(Number(x).toFixed(PRECISION[cur]??2));
const addMonthsAnchored=(date,anchor)=>{const [y,m]=date.split('-').map(Number);const nextY=y+(m===12?1:0),nextM=m===12?1:m+1;const last=new Date(nextY,nextM,0).getDate();return `${nextY}-${String(nextM).padStart(2,'0')}-${String(Math.min(Number(anchor)||1,last)).padStart(2,'0')}`;};
const checkAccountingType=c=>c.treatment==='income'?'income':c.treatment==='expense'?'expense':c.direction==='incoming'?'capital_in':'capital_out';
function installmentSchedule(d){const count=Number(d.installmentCount)||0;if(!count||!isISODate(d.installmentStart))return [];const precision=PRECISION[d.currency]??2;let allocated=0,paid=debtPaid(d);return Array.from({length:count},(_,i)=>{const amount=i===count-1?roundCur(d.amount-allocated,d.currency):Number((d.amount/count).toFixed(precision));allocated=roundCur(allocated+amount,d.currency);const paidHere=Math.max(0,Math.min(amount,paid));paid=roundCur(paid-paidHere,d.currency);return {number:i+1,date:addMonths(d.installmentStart,i),amount,paid:paidHere,remaining:roundCur(amount-paidHere,d.currency)};});}
function accountMovements(accountId){const entries=[];for(const t of ws().transactions){if(t.type==='transfer'){if(t.fromAccountId===accountId)entries.push({date:t.date,amount:-Number(t.amount),label:'انتقال به '+accountName(t.toAccountId),ref:t.id});if(t.toAccountId===accountId)entries.push({date:t.date,amount:Number(t.receivedAmount??t.amount),label:'انتقال از '+accountName(t.fromAccountId),ref:t.id});}else if(t.accountId===accountId){entries.push({date:t.date,amount:((t.type==='income'||t.type==='capital_in')?1:-1)*Number(t.amount),label:typeLabel(t.type)+(t.party?' · '+t.party:''),ref:t.id});}}
for(const d of ws().debts)for(const t of d.settlements||[])if(t.accountId===accountId)entries.push({date:t.date,amount:(d.direction==='receivable'?1:-1)*Number(t.amount),label:(d.direction==='receivable'?'وصول طلب':'پرداخت بدهی')+' · '+d.person,ref:t.id});
for(const c of ws().checks||[])if(c.status==='cleared'&&!c.debtId&&c.accountId===accountId)entries.push({date:c.clearedDate||c.dueDate,amount:(c.direction==='incoming'?1:-1)*Number(c.amount),label:'چک '+c.number+' · '+c.party,ref:c.id});
return entries.sort((a,b)=>b.date.localeCompare(a.date));}

function accountBalances(){const balances=new Map(ws().accounts.map(a=>[a.id,Number(a.openingBalance)||0]));const add=(id,delta)=>{if(balances.has(id))balances.set(id,balances.get(id)+Number(delta));};
 for(const t of ws().transactions){if(t.type==='transfer'){add(t.fromAccountId,-Number(t.amount));add(t.toAccountId,Number(t.receivedAmount??t.amount));}else add(t.accountId,((t.type==='income'||t.type==='capital_in')?1:-1)*Number(t.amount));}
 for(const d of ws().debts)for(const t of d.settlements||[])add(t.accountId,(d.direction==='receivable'?1:-1)*Number(t.amount));
 for(const c of ws().checks||[])if(c.status==='cleared'&&!c.debtId)add(c.accountId,(c.direction==='incoming'?1:-1)*Number(c.amount));
 for(const a of ws().accounts)balances.set(a.id,roundCur(balances.get(a.id)||0,a.currency));return balances;}

function monthSummary(month,cur){let income=0,expense=0,capitalIn=0,capitalOut=0,settleIn=0,settleOut=0;for(const t of ws().transactions){if(jalaliKey(t.date)!==month||t.type==='transfer')continue;const a=findAccount(t.accountId);if(!a||a.currency!==cur)continue;if(t.type==='income')income+=t.amount;else if(t.type==='expense')expense+=t.amount;else if(t.type==='capital_in')capitalIn+=t.amount;else if(t.type==='capital_out')capitalOut+=t.amount}
 for(const d of ws().debts)for(const s of d.settlements||[]){if(jalaliKey(s.date)!==month||d.currency!==cur)continue;if(d.direction==='receivable')settleIn+=s.amount;else settleOut+=s.amount}
 for(const c of ws().checks||[]){if(c.status!=='cleared'||c.debtId||!c.clearedDate||jalaliKey(c.clearedDate)!==month||c.currency!==cur)continue;const mode=checkAccountingType(c);if(mode==='income')income+=c.amount;else if(mode==='expense')expense+=c.amount;else if(mode==='capital_in')capitalIn+=c.amount;else capitalOut+=c.amount;}
return {income,expense,capitalIn,capitalOut,settleIn,settleOut,net:income-expense,cashFlow:income-expense+capitalIn-capitalOut+settleIn-settleOut};}
function recentMonths(n){const j=jalaliParts(today()),current=j.year*12+j.month-1,r=[];for(let i=n-1;i>=0;i--){const value=current-i,y=Math.floor(value/12),m=value%12+1;r.push(`${y}-${String(m).padStart(2,'0')}`)}return r}
function activityRows(){const rows=ws().transactions.map(t=>({...t,kind:'tx'}));for(const d of ws().debts)for(const s of d.settlements||[])rows.push({id:s.id,date:s.date,type:d.direction==='receivable'?'settle_in':'settle_out',amount:s.amount,accountId:s.accountId,category:'بدهی و طلب',party:d.person,note:s.note,kind:'settlement',debtId:d.id});for(const c of ws().checks||[])if(c.status==='cleared'&&!c.debtId)rows.push({id:c.id,date:c.clearedDate||c.dueDate,type:checkAccountingType(c),amount:c.amount,accountId:c.accountId,category:'چک',party:c.party,note:'چک شماره '+c.number,kind:'check',checkId:c.id});
return rows.sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.time||'').localeCompare(a.time||'')||(b.createdAt||'').localeCompare(a.createdAt||''))}
function baseSelectAccounts(selected='',currency='',exclude=''){const filtered=ws().accounts.filter(a=>(!currency||a.currency===currency)&&a.id!==exclude);return `<option value="">انتخاب حساب</option>`+filtered.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${esc(a.name)} · ${esc(CURRENCIES[a.currency])}</option>`).join('')}
function empty(title,subtitle,action='',label=''){return `<div class="empty"><div class="empty-art"><span class="empty-orbit orbit-one"></span><span class="empty-orbit orbit-two"></span><span class="empty-core">${icon('wallets',32)}</span></div><h4>${esc(title)}</h4><p>${esc(subtitle)}</p>${action?`<button class="btn primary" data-action="${action}">${icon('plus',16)} ${esc(label)}</button>`:''}</div>`}
function toast(message){const r=document.getElementById('toast-root');r.innerHTML=`<div class="toast">${esc(locale()==='en'?(window.HY_I18N?.translate(message)||message):message)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>r.innerHTML='',4300)}
function navButton(id,label,ic){return `<button data-action="nav" data-page="${id}" class="nav-item ${state.page===id?'active':''}" aria-current="${state.page===id?'page':'false'}"><span class="nav-symbol">${icon(ic,20)}</span><span>${label}</span>${state.page===id?`<span class="nav-active-dot"></span>`:''}</button>`}
function workspacePicker(compact=false){return `<div class="workspace-switch ${compact?'compact':''}" role="group" aria-label="انتخاب دفتر مالی"><button class="${state.workspace==='personal'?'selected':''}" data-action="workspace" data-workspace="personal">${icon('user',17)} <span>شخصی</span></button><button class="${state.workspace==='business'?'selected':''}" data-action="workspace" data-workspace="business">${icon('briefcase',17)} <span>کسب‌وکار</span></button></div>`}
function applyThemeBranding(theme){
 // The three strokes keep the exact Journal logo geometry. Only the palette changes.
 const active=THEME_OPTIONS.some(([id])=>id===theme)?theme:'studio';
 const iconLink=document.querySelector('link[rel="icon"]');
 const appleLink=document.querySelector('link[rel="apple-touch-icon"]');
 const manifestLink=document.querySelector('link[rel="manifest"]');
 const metaTheme=document.querySelector('meta[name="theme-color"]');
 if(iconLink)iconLink.href=`themes/${active}.svg`;
 if(appleLink)appleLink.href=`themes/${active}-180.png`;
 if(manifestLink)manifestLink.href=`themes/${active}.webmanifest`;
 const browserChromeColors={studio:'#465FC7',night:'#101B2E',sage:'#347766',obsidian:'#1D1712',platinum:'#F3F5F8',royal:'#18203A',rose:'#2B1923',emerald:'#172924',sand:'#F7F1E8'};
 if(metaTheme)metaTheme.content=browserChromeColors[active];
 return active;
}
