const GUIDE_GROUPS={all:['همه موضوعات','All topics'],start:['شروع کار','Getting started'],daily:['عملیات روزانه','Daily operations'],analysis:['گزارش و تحلیل','Reports & insights'],control:['تنظیمات و امنیت','Settings & safety']};
const GUIDE_FAQ=[
 [['آیا برای استفاده باید ثبت‌نام کنم؟','Do I need an account?'],['خیر. اطلاعات در مرورگر فعلی ذخیره می‌شود و حساب کاربری یا همگام‌سازی ابری وجود ندارد.','No. Data is stored in this browser; there is no account or cloud sync.']],
 [['اگر مرورگر را پاک کنم چه می‌شود؟','What if I clear my browser data?'],['ممکن است سوابق پاک شوند. مرتب از بخش تنظیمات فایل پشتیبان JSON بگیر و در محل امن نگه دار.','Your records may be lost. Export a JSON backup regularly from Settings and keep it somewhere safe.']],
 [['درآمد با ورودی سرمایه چه فرقی دارد؟','Income vs capital inflow?'],['درآمد در گزارش سود و هزینه حساب می‌شود؛ ورودی سرمایه موجودی را زیاد می‌کند اما درآمد عملیاتی نیست.','Income contributes to the profit report; capital inflow increases balance but is not operating income.']],
 [['چرا موجودی دلار و تومان با هم جمع نمی‌شوند؟','Why are USD and Toman not combined?'],['چون نرخ تبدیل خودکار وجود ندارد و جمع‌زدن ارزهای مختلف گمراه‌کننده است. هر ارز را جداگانه بررسی کن.','There is no automatic exchange rate; combining different currencies would be misleading. Review each currency separately.']]
];
const TOUR_STEPS=[
 {page:'dashboard',selector:'.mobile-workspace .workspace-switch, .sidebar-workspace .workspace-switch',fa:['دو دفتر مستقل','اینجا بین دفتر شخصی و کسب‌وکار جابه‌جا می‌شوی. اطلاعات هر دفتر مستقل می‌ماند.'],en:['Choose your ledger','Switch between Personal and Business. Their records stay separate.']},
 {page:'accounts',selector:'.section-heading [data-action="new-account"]',fa:['اولین حساب را بساز','این دکمه فرم حساب بانکی، وجه نقد یا کیف پول را باز می‌کند. موجودی اولیه را دقیق وارد کن.'],en:['Create your first account','This button opens the bank, cash or wallet form. Enter the opening balance carefully.']},
 {page:'transactions',selector:'.section-heading [data-action="new-tx"]',fa:['درآمد و هزینه ثبت کن','از اینجا درآمد، هزینه، انتقال و ورودی یا خروجی سرمایه را ثبت می‌کنی.'],en:['Record transactions','Add income, expenses, transfers and capital movements here.']},
 {page:'debts',selector:'.section-heading [data-action="new-debt"]',fa:['بدهی و طلب را پیگیری کن','اشخاص، مبالغ و سررسیدها را ثبت کن؛ پرداخت‌ها را بعداً با «ثبت تسویه» وارد کن.'],en:['Track debts and receivables','Record contacts, amounts and due dates, then record settlements as payments occur.']},
 {page:'reports',selector:'[data-action="new-budget"]',fa:['بودجه و گزارش‌ها','اینجا گزارش ماهانه را می‌بینی و برای هر دسته هزینه سقف بودجه تعریف می‌کنی.'],en:['Budgets and reports','Review monthly insights and set spending limits for expense categories.']},
 {page:'settings',selector:'[data-action="backup"]',fa:['از اطلاعاتت محافظت کن','حتماً از هر دو دفتر فایل پشتیبان بگیر. پاک کردن اطلاعات مرورگر ممکن است سوابق را از بین ببرد.'],en:['Protect your records','Back up both ledgers. Clearing browser data may erase your records.']}
];
const gt=(fa,en)=>locale()==='en'?en:fa;
const guideTopic=id=>GUIDE_TOPICS.find(t=>t.id===id)||GUIDE_TOPICS[0];
const guideTitle=t=>t[locale()==='en'?'en':'fa'][0];
const guideDescription=t=>t[locale()==='en'?'en':'fa'][1];
const guideSteps=t=>t[locale()==='en'?'en':'fa'][2];
const guideTip=t=>t[locale()==='en'?'en':'fa'][3];
function guideDetailHtml(t){return `<div class="guide-detail"><p class="guide-detail-lead">${esc(guideDescription(t))}</p><div class="guide-detail-label">${gt('مراحل انجام کار','Step by step')}</div><ol class="guide-steps">${guideSteps(t).map((s,i)=>`<li><span class="guide-step-number">${i+1}</span><span>${esc(s)}</span></li>`).join('')}</ol><div class="guide-tip">${icon('info',20)}<p><strong>${gt('نکته مهم','Important tip')}</strong><span>${esc(guideTip(t))}</span></p></div><button class="btn primary guide-detail-cta" data-action="guide-open" data-id="${t.id}">${icon('arrow',16)} ${gt('رفتن به این بخش','Go to this section')}</button></div>`}
function openGuideDetail(id){const t=guideTopic(id);showModal(guideTitle(t),guideDetailHtml(t));}
function filteredGuideTopics(){const q=state.guideQuery.trim().toLocaleLowerCase();return GUIDE_TOPICS.filter(t=>(state.guideGroup==='all'||t.group===state.guideGroup)&&(!q||[...t.fa.slice(0,2),...t.en.slice(0,2),...t.fa[2],...t.en[2]].join(' ').toLocaleLowerCase().includes(q)));}
function renderGuideCards(){const topics=filteredGuideTopics();return topics.length?topics.map(t=>`<button type="button" class="guide-card" data-action="guide-detail" data-id="${t.id}"><span class="guide-card-icon">${icon(t.ic,23)}</span><span class="guide-card-body"><span class="guide-card-group">${esc(GUIDE_GROUPS[t.group][locale()==='en'?1:0])}</span><strong>${esc(guideTitle(t))}</strong><span class="guide-card-summary">${esc(guideDescription(t))}</span><span class="guide-card-footer">${gt('آموزش مرحله‌به‌مرحله','Step-by-step guide')} ${icon('arrow',15)}</span></span></button>`).join(''):`<div class="guide-no-results">${icon('search',25)}<strong>${gt('راهنمایی پیدا نشد','No guides found')}</strong><p>${gt('عبارت دیگری جست‌وجو کن یا دسته‌بندی را تغییر بده.','Try another search or choose a different category.')}</p></div>`;}
function updateGuideResults(){const results=document.getElementById('guide-results');if(results)results.innerHTML=renderGuideCards();const count=document.getElementById('guide-count');if(count)count.textContent=gt(`${filteredGuideTopics().length} موضوع آموزشی`,`${filteredGuideTopics().length} guides`);document.querySelectorAll('[data-action="guide-filter"]').forEach(b=>{const active=b.dataset.group===state.guideGroup;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}
function renderHelp(){return `<div class="help-center"><section class="help-hero"><div class="help-hero-ornament">${icon('book',92)}</div><div class="help-hero-copy"><span class="help-kicker">QABBILE / HESABYAR ACADEMY</span><h3>${gt('راهنمای حساب‌یار','Hesabyar Help Center')}</h3><p>${gt('هر قابلیتی را به زبان ساده یاد بگیر؛ از ساخت اولین حساب تا گزارش‌گیری و محافظت از اطلاعات.','Learn every feature in plain language, from your first account to reporting and data safety.')}</p><div class="help-hero-actions"><button class="help-start" data-action="guide-tour-start">${icon('plus',17)} ${gt('شروع آموزش تعاملی','Start interactive tour')}</button><span>${icon('check',15)} ${gt('بدون تغییر اطلاعات مالی','Your financial data stays unchanged')}</span></div></div></section><section class="help-search-panel"><div class="help-search-field">${icon('search',21)}<input class="field" type="search" data-guide-search value="${esc(state.guideQuery)}" placeholder="${gt('جست‌وجو در راهنماها...','Search the guides...')}" aria-label="${gt('جست‌وجو در راهنماها','Search guides')}"/></div><div class="help-groups" role="group" aria-label="${gt('دسته‌بندی راهنما','Guide categories')}">${Object.entries(GUIDE_GROUPS).map(([id,names])=>`<button type="button" data-action="guide-filter" data-group="${id}" class="help-filter ${state.guideGroup===id?'active':''}" aria-pressed="${state.guideGroup===id}">${esc(names[locale()==='en'?1:0])}</button>`).join('')}</div><div class="help-list-head"><h3>${gt('آموزش امکانات','Explore features')}</h3><span id="guide-count">${gt(`${filteredGuideTopics().length} موضوع آموزشی`,`${filteredGuideTopics().length} guides`)}</span></div><div id="guide-results" class="guide-grid">${renderGuideCards()}</div></section><section class="help-faq"><div class="help-faq-head"><span class="help-faq-mark">${icon('info',21)}</span><div><h3>${gt('سؤال‌های پرتکرار','Frequently asked questions')}</h3><p>${gt('پاسخ‌های کوتاه به نکات مهم مالی و امنیت اطلاعات','Quick answers about finance and data safety')}</p></div></div>${GUIDE_FAQ.map((q,i)=>`<details class="help-faq-item"><summary>${esc(q[0][locale()==='en'?1:0])}${icon('plus',17)}</summary><p>${esc(q[1][locale()==='en'?1:0])}</p></details>`).join('')}</section><section class="panel spaced" style="margin-top:20px"><h3>راهنمای قابلیت‌های جدید ۲.۴.۱</h3><p>یادآور سررسیدها: از زنگ بالای صفحه وارد بخش یادآورها شو. چک‌های پاس‌نشده و اقساط دارای مانده به ترتیب سررسید نشان داده می‌شوند. فاصله هشدار را در تنظیمات انتخاب کن.</p><p>تصویر چک: هنگام ثبت یا ویرایش چک، تصویر روی چک و پشت چک را اضافه کن؛ هر تصویر تا ۲ مگابایت. تصاویر در فایل پشتیبان هم ذخیره می‌شوند.</p><p>قفل PIN: در تنظیمات یک PIN شش تا دوازده‌رقمی انتخاب کن. پس از فعال‌سازی، هر بار که برنامه را باز کنی PIN لازم است. این قفل داده‌های مرورگر را رمزگذاری نمی‌کند.</p></section><div class="help-endnote">${icon('shield',19)}<span>${gt('حساب‌یار اطلاعات را فقط در مرورگر شما ذخیره می‌کند؛ تهیه پشتیبان منظم را فراموش نکن.','Hesabyar stores data in your browser only. Remember to back up regularly.')}</span><button data-action="guide-open" data-id="backup">${gt('آموزش پشتیبان‌گیری','Backup guide')}</button></div></div>`;}
function showGuideWelcome(){const root=document.getElementById('guide-welcome-root');if(!root)return;root.innerHTML=`<div class="guide-welcome-backdrop"><div class="guide-welcome" role="dialog" aria-modal="true" aria-labelledby="welcome-title"><div class="guide-welcome-emblem">${icon('book',34)}</div><span class="guide-welcome-kicker">HESABYAR / GETTING STARTED</span><h2 id="welcome-title">${gt('به حساب‌یار خوش آمدی','Welcome to Hesabyar')}</h2><p>${gt('با یک آموزش کوتاه، مسیر ساخت حساب، ثبت تراکنش و گرفتن پشتیبان را یاد بگیر.','A quick walkthrough will show you how to create accounts, record transactions and back up your data.')}</p><div class="guide-welcome-points"><span>${icon('check',16)} ${gt('۶ مرحله کوتاه','6 short steps')}</span><span>${icon('check',16)} ${gt('بدون تغییر اطلاعات','No data changes')}</span><span>${icon('check',16)} ${gt('قابل رد کردن','Skip anytime')}</span></div><div class="guide-welcome-actions"><button class="btn primary" data-action="guide-intro-start">${gt('شروع آموزش','Start tour')} ${icon('arrow',17)}</button><button class="btn secondary" data-action="guide-intro-dismiss">${gt('بعداً یاد می‌گیرم','Maybe later')}</button></div></div></div>`;}
async function dismissGuideWelcome(){document.getElementById('guide-welcome-root').innerHTML='';state.data.settings.guideIntroSeen=true;try{await persist()}catch(e){console.warn('Guide intro preference could not be saved',e)}}
function showTourStep(step){if(step<0||step>=TOUR_STEPS.length){endTour();return}state.tourActive=true;state.tourStep=step;state.page=TOUR_STEPS[step].page;state.menu=false;closeModal();renderShell();window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(updateTourOverlay);}
function endTour(){state.tourActive=false;state.tourStep=-1;document.getElementById('tour-root').innerHTML='';}
function updateTourOverlay(){if(!state.tourActive)return;const s=TOUR_STEPS[state.tourStep],root=document.getElementById('tour-root');if(!s||!root)return;const matches=[...document.querySelectorAll(s.selector)];const target=matches.find(el=>{const r=el.getBoundingClientRect(),style=getComputedStyle(el);return r.width>0&&r.height>0&&style.display!=='none'&&style.visibility!=='hidden'})||document.querySelector('.topbar');if(!target)return;let rect=target.getBoundingClientRect();if(rect.top<8||rect.bottom>innerHeight-10){target.scrollIntoView({block:'center',behavior:'instant'});rect=target.getBoundingClientRect();}const pad=6,left=Math.max(6,rect.left-pad),top=Math.max(6,rect.top-pad),width=Math.min(innerWidth-left-6,rect.width+pad*2),height=rect.height+pad*2;const mobile=innerWidth<=650,popWidth=Math.min(360,innerWidth-24);let popTop=rect.bottom+17;if(popTop+255>innerHeight)popTop=Math.max(12,rect.top-260);if(popTop+240>innerHeight)popTop=Math.max(12,innerHeight-255);const popLeft=Math.max(12,Math.min(innerWidth-popWidth-12,rect.left));const [title,desc]=s[locale()==='en'?'en':'fa'];root.innerHTML=`<div class="tour-spotlight" style="left:${left}px;top:${top}px;width:${width}px;height:${height}px"></div><div class="tour-card" role="dialog" aria-label="${gt('آموزش تعاملی','Interactive tour')}" style="${mobile?'':`top:${popTop}px;left:${popLeft}px;width:${popWidth}px;`}"><div class="tour-top"><span>${gt('آموزش تعاملی حساب‌یار','Hesabyar guided tour')}</span><button data-action="guide-tour-close" aria-label="${gt('بستن آموزش','Close tour')}">${icon('plus',17)}</button></div><div class="tour-progress" aria-label="${state.tourStep+1} / ${TOUR_STEPS.length}">${TOUR_STEPS.map((_,i)=>`<i class="${i<=state.tourStep?'done':''}"></i>`).join('')}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p><div class="tour-bottom"><span>${state.tourStep+1} / ${TOUR_STEPS.length}</span><div><button class="btn sm secondary" data-action="guide-tour-prev" ${state.tourStep===0?'disabled':''}>${gt('قبلی','Back')}</button><button class="btn sm primary" data-action="guide-tour-next">${state.tourStep===TOUR_STEPS.length-1?gt('پایان آموزش','Finish'):gt('مرحله بعد','Next')}</button></div></div></div>`;}

function renderShell(){
 const activeTheme=applyThemeBranding(state.data.settings.theme||'studio');
 document.body.dataset.theme=activeTheme;
 const titles={reminders:'یادآور سررسیدها',dashboard:'داشبورد',transactions:'گردش حساب‌ها',accounts:'حساب‌ها و کیف پول‌ها',debts:'طلب‌ها و بدهی‌ها',checks:'مدیریت چک‌ها',recurring:'تراکنش‌های دوره‌ای',goals:'اهداف پس‌انداز',reports:'گزارش‌های مالی',settings:'تنظیمات',help:'راهنمای حساب‌یار'};
 const descriptions={reminders:'هشدار چک‌ها و اقساط نزدیک و عقب‌افتاده',dashboard:'همه چیز درباره وضعیت مالی، در یک نگاه',transactions:'ریز تمام ورودی‌ها، خروجی‌ها و انتقال‌ها',accounts:'مانده واقعی حساب‌های بانکی و کیف پول‌ها',debts:'پیگیری دقیق طلب‌ها، بدهی‌ها و تسویه‌ها',checks:'چک‌های دریافتی و پرداختی، سررسید و وصول',recurring:'ثبت کنترل‌شده هزینه‌ها و درآمدهای تکراری',goals:'پیگیری پیشرفت پس‌انداز و برنامه مالی',reports:'تحلیل درآمد، هزینه و بودجه‌بندی',settings:'شخصی‌سازی و پشتیبان‌گیری از اطلاعات',help:'آموزش قدم‌به‌قدم تمام بخش‌های برنامه'};
 const isPersonal=state.workspace==='personal';
 document.getElementById('app').innerHTML=`
 <div class="mobile-scrim ${state.menu?'show':''}" data-action="close-menu"></div>
 <aside class="sidebar ${state.menu?'open':''}">
  <div class="brand"><div class="brand-logo tribe-logo"><img src="themes/${activeTheme}.svg" width="48" height="48" alt="نشان سه‌خطی قبیله" decoding="async"></div><div class="brand-text"><h1>حساب‌یار<span class="brand-dot">.</span></h1><p>Qabbile finance studio</p></div><button class="mobile-menu-close" data-action="close-menu" aria-label="بستن فهرست">×</button></div>
  <div class="sidebar-workspace"><span class="side-caption">دفتر فعال</span>${workspacePicker()}<div class="workspace-hint"><span class="workspace-status"></span> ${isPersonal?'فضای مالی شخصی':'فضای مالی کسب‌وکار'} <span class="workspace-hint-spacer">·</span> مستقل روی این دستگاه</div></div>
  <div class="nav-section"><div class="side-label">مدیریت روزانه</div><nav class="nav" aria-label="فهرست اصلی">${navButton('dashboard','نمای کلی','dashboard')}${navButton('transactions','تراکنش‌ها','transactions')}${navButton('accounts','حساب‌ها و کیف پول‌ها','wallets')}${navButton('debts','طلب‌ها و بدهی‌ها','debts')}${navButton('checks','مدیریت چک‌ها','receipt')}${navButton('reminders','یادآور سررسیدها','bell')}${navButton('recurring','تراکنش‌های دوره‌ای','calendar')}${navButton('goals','اهداف پس‌انداز','chart')}${navButton('reports','تحلیل و گزارش‌ها','reports')}</nav></div>
  <div class="nav-section preferences"><div class="side-label">ابزارها</div><nav class="nav">${navButton('help','راهنمای استفاده','book')}${navButton('settings','تنظیمات و پشتیبان','settings')}</nav></div>
  <div class="sidebar-foot"><span class="footer-lock">${icon('shield',19)}</span><div><b>اطلاعات تحت کنترل شما</b><p>ذخیره محلی در همین مرورگر</p></div></div>
 </aside>
 <main class="main safe-area">
  <header class="topbar"><div class="topbar-left"><button class="icon-btn menu-toggle" data-action="toggle-menu" aria-label="باز کردن منو">${icon('menu',22)}</button><div class="top-title"><p class="page-hello">${isPersonal?'دفتر شخصی':'دفتر کسب‌وکار'} <span class="separator-dot">•</span> ${fmtDate(today())}</p><div class="top-heading-row"><h2>${titles[state.page]}</h2>${state.page!=='help'?`<button type="button" class="page-help-btn" data-action="help-context" aria-label="راهنمای این بخش" title="راهنمای این بخش">${icon('info',17)} <span>راهنما</span></button>`:''}</div><p class="top-desc">${descriptions[state.page]}</p></div></div><div class="top-actions"><button type="button" class="reminder-top-btn" data-action="nav" data-page="reminders" aria-label="یادآور سررسیدها" title="یادآور سررسیدها">${icon('bell',19)}${reminderBadge()?`<span class="reminder-counter">${reminderBadge()>99?'99+':reminderBadge()}</span>`:''}</button>${state.data.settings.pinLock?`<button type="button" class="reminder-top-btn" data-action="pin-lock" title="قفل کردن حساب‌یار" aria-label="قفل کردن حساب‌یار">${icon('lock',18)}</button>`:''}<button class="language-toggle" data-action="switch-language" aria-label="Switch language / تغییر زبان" title="Switch language / تغییر زبان"><span class="language-glyph">🌐</span><span>${locale()==='en'?'فارسی':'EN'}</span></button><span class="secure-indicator">${icon('shield',15)} محلی و خصوصی</span><button class="btn primary header-add" data-action="new-tx">${icon('plus',20)} <span>ثبت تراکنش</span></button></div></header>
  <div class="mobile-workspace">${workspacePicker(true)}</div>
  <div class="page-entry">${renderPage()}</div>
  <footer class="footer-note"><span>حساب‌یار ۲.۴.۱</span><span>اطلاعات روی دستگاه شماست؛ مرتب پشتیبان بگیرید.</span></footer>
 </main>
 <nav class="mobile-bar" aria-label="منوی پایین موبایل">${[['dashboard','خانه','dashboard'],['transactions','گردش‌ها','transactions'],['accounts','حساب‌ها','wallets'],['reports','گزارش‌ها','reports'],['settings','بیشتر','menu']].map(([page,label,ic])=>`<button class="${state.page===page?'selected':''}" data-action="${page==='settings'?'toggle-menu':'nav'}" data-page="${page}">${icon(ic,21)}<span>${label}</span></button>`).join('')}</nav>`;
 localize(document.getElementById('app'));
 if(state.tourActive)requestAnimationFrame(updateTourOverlay);
}
function renderPage(){switch(state.page){case'reminders':return renderReminders();case'dashboard':return renderDashboard();case'transactions':return renderTransactions();case'accounts':return renderAccounts();case'debts':return renderDebts();case'checks':return renderChecks();case'recurring':return renderRecurring();case'goals':return renderGoals();case'reports':return renderReports();case'settings':return renderSettings();case'help':return renderHelp();default:return renderDashboard()}}
function stat(title,n,cur,ic,color,foot){return `<div class="stat-card"><div class="stat-top"><span class="stat-caption">${title}</span><span class="stat-icon">${icon(ic,20)}</span></div><div class="stat-value ${color||''}"><b>${money(n,cur)}</b> <span class="stat-unit">${CURRENCIES[cur]}</span></div><div class="stat-foot">${foot||''}</div></div>`}
function chartMonths(cur){const months=recentMonths(6),summaries=months.map(m=>monthSummary(m,cur)),max=Math.max(1,...summaries.flatMap(m=>[m.income,m.expense]));const hasData=summaries.some(m=>m.income||m.expense);return `<div class="chart-stage ${hasData?'':'chart-is-empty'}"><div class="chart-grid"><div></div><div></div><div></div><div></div></div><div class="simple-chart" aria-label="نمودار درآمد و هزینه ۶ ماه اخیر">${months.map((m,i)=>`<div class="chart-group"><div class="chart-bars"><div class="chart-bar income" title="درآمد: ${money(summaries[i].income,cur)}" style="height:${summaries[i].income?Math.max(3,summaries[i].income/max*100):0}%"></div><div class="chart-bar expense" title="هزینه: ${money(summaries[i].expense,cur)}" style="height:${summaries[i].expense?Math.max(3,summaries[i].expense/max*100):0}%"></div></div><div class="chart-label">${locale()==='en'?(window.HY_I18N?.months[Number(m.slice(5))-1]||''):esc(PERSIAN_MONTHS[Number(m.slice(5))-1])}</div></div>`).join('')}</div>${!hasData?`<div class="chart-empty"><span>${icon('chart',26)}</span><b>نمودار شما از اولین ثبت ساخته می‌شود</b><small>هنوز درآمد یا هزینه‌ای ثبت نشده است.</small></div>`:''}</div><div class="legend"><span><i class="dot income"></i> درآمد</span><span><i class="dot expense"></i> هزینه</span></div>`}
function renderDashboard(){
 const cur=ws().reportCurrency,bals=accountBalances(),sum=monthSummary(monthNow(),cur),total=ws().accounts.filter(a=>a.currency===cur).reduce((x,a)=>x+(bals.get(a.id)||0),0),tx=activityRows().slice(0,5),isPersonal=state.workspace==='personal';
 const accCount=ws().accounts.length;
 return `<section class="hero">
  <div class="hero-decor hero-ring-one"></div><div class="hero-decor hero-ring-two"></div><div class="hero-graphic"><span class="graphic-line l1"></span><span class="graphic-line l2"></span><span class="graphic-line l3"></span><span class="graphic-line l4"></span><span class="graphic-line l5"></span><span class="graphic-line l6"></span></div>
  <div class="hero-main"><div class="hero-eyebrow"><span class="pulse-dot"></span> نمای مالی ${isPersonal?'شخصی':'کسب‌وکار'} <span class="hero-divider">/</span> ${fmtMonth(monthNow())}</div><h3>هر تصمیم بهتر، از یک تصویر روشن شروع می‌شود.</h3><div class="hero-money-label">موجودی کل به ارز انتخابی</div><div class="hero-value"><strong>${money(total,cur)}</strong><span>${CURRENCIES[cur]}</span></div><div class="hero-actions"><button class="hero-btn" data-action="new-tx">${icon('plus',18)} ثبت تراکنش جدید</button><button class="hero-link" data-action="nav" data-page="accounts">مشاهده حساب‌ها ${icon('arrow',15)}</button></div></div>
  <div class="hero-currency"><span>ارز نمایش</span><select class="select currency-select" data-action-change="currency" aria-label="ارز نمایش">${currencyOptions(cur)}</select></div>
  </section>
  ${!accCount?`<section class="onboard"><div class="onboard-icon">${icon('wallets',26)}</div><div class="onboard-info"><b>اولین قدم: حساب مالی خودت را اضافه کن</b><p>یک حساب بانکی، نقدی یا کیف پول بساز تا همه گردش‌ها با دقت محاسبه شوند.</p></div><button class="btn primary" data-action="new-account">${icon('plus',18)} ساخت اولین حساب</button></section>`:''}
  <section class="metrics-section"><div class="content-section-header"><div><p class="eyebrow">خلاصه ماه جاری</p><h3>اعداد مهم در یک نگاه</h3></div><span class="subtle-note">${fmtMonth(monthNow())} · ${CURRENCIES[cur]}</span></div><div class="grid-stats">${stat('درآمد ثبت‌شده',sum.income,cur,'income','color-green','فقط درآمد واقعی')}${stat('هزینه‌های ثبت‌شده',sum.expense,cur,'expense','color-red','فقط هزینه واقعی')}${stat('خالص درآمد و هزینه',sum.net,cur,'reports',sum.net>=0?'color-accent':'color-red','بدون گردش سرمایه و انتقال')}${stat('تغییر نقدینگی',sum.cashFlow,cur,'transfer',sum.cashFlow>=0?'':'color-red','شامل تسویه‌ها و گردش سرمایه')}</div></section>
  <div class="columns-2 spaced"><section class="panel chart-panel"><div class="split-title"><div><p class="eyebrow">بررسی روند</p><h3>درآمد و هزینه‌ها</h3><p class="panel-sub">در شش ماه گذشته · ${CURRENCIES[cur]}</p></div><span class="panel-corner-icon">${icon('chart',21)}</span></div>${chartMonths(cur)}</section>
  <section class="panel accounts-panel"><div class="split-title"><div><p class="eyebrow">دارایی‌های نقدی</p><h3>حساب‌های من</h3><p class="panel-sub">موجودی هر حساب به ارز خودش</p></div><button class="text-btn" data-action="nav" data-page="accounts">همه حساب‌ها ${icon('arrow',15)}</button></div><div class="accounts-content">${accCount?ws().accounts.slice(0,5).map(a=>accountRow(a,bals.get(a.id)||0)).join(''):empty('هنوز حسابی وجود ندارد','برای شروع، یک حساب اضافه کن.','new-account','حساب جدید')}</div></section></div>
  <section class="panel spaced recent-panel"><div class="split-title"><div><p class="eyebrow">فعالیت اخیر</p><h3>آخرین تراکنش‌ها</h3><p class="panel-sub">همه دریافت‌ها و پرداخت‌های همین دفتر</p></div><button class="text-btn" data-action="nav" data-page="transactions">نمایش همه ${icon('arrow',15)}</button></div><div class="recent-content">${tx.length?tx.map(rowRecent).join(''):empty('هنوز تراکنشی ثبت نشده','اولین ورودی یا خروجی را ثبت کن تا این بخش کامل شود.','new-tx','ثبت اولین تراکنش')}</div></section>`
}
function accountRow(a,b){const ic=a.type==='bank'?'bank':a.type==='cash'?'cash':'wallet';return `<div class="account-row"><span class="item-icon">${icon(ic)}</span><div class="item-info"><div class="item-title">${esc(a.name)}</div><div class="item-meta">${ACCOUNT_TYPES[a.type]||'حساب'} · ${a.currency}</div></div><div class="item-amount">${amountLabel(b,a.currency)}</div></div>`}
function rowRecent(t){let cur=t.type==='transfer'?findAccount(t.fromAccountId)?.currency:findAccount(t.accountId)?.currency;cur=cur||'IRT';const account=t.type==='transfer'?`${accountName(t.fromAccountId)} ← ${accountName(t.toAccountId)}`:accountName(t.accountId);const label=t.type==='transfer'?`انتقال · ${esc(account)}`:esc(t.category||t.party||typeLabel(t.type));return `<div class="tx-row"><span class="item-icon">${icon(t.type==='transfer'?'transfer':(['income','capital_in','settle_in'].includes(t.type)?'income':'expense'))}</span><div class="item-info"><div class="item-title">${label}</div><div class="item-meta">${fmtDate(t.date)}${t.time?' · '+esc(t.time):''} · ${esc(t.party||account)}</div></div><div class="item-amount ${typeColor(t.type)}">${['income','capital_in','settle_in'].includes(t.type)?'+':['expense','capital_out','settle_out'].includes(t.type)?'−':''}${amountLabel(t.amount,cur)}</div></div>`}
function renderAccounts(){const bals=accountBalances();return `<div class="section-heading"><div><h3>حساب‌ها و موجودی‌ها</h3><p>هر حساب با ارز اختصاصی و مانده محاسبه‌شده از گردش‌ها.</p></div><button class="btn primary" data-action="new-account">${icon('plus')} حساب جدید</button></div><div class="section-note">${icon('info')}مانده هر حساب = موجودی آغازین + تمام ورودی‌ها − تمام خروجی‌ها. هیچ تبدیل ارزی خودکاری انجام نمی‌شود.</div><div class="grid-stats spaced" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))">${ws().accounts.length?ws().accounts.map(a=>`<section class="account-tile"><div class="account-tile-head"><span class="item-icon">${icon(a.type==='bank'?'bank':a.type==='cash'?'cash':'wallet')}</span><div class="item-info"><div class="item-title">${esc(a.name)}</div><div class="item-meta">${ACCOUNT_TYPES[a.type]} · ${CURRENCIES[a.currency]}</div></div></div><div class="amount">${amountLabel(bals.get(a.id)||0,a.currency)}</div><div class="flex-between"><span class="tag">موجودی اولیه: ${money(a.openingBalance,a.currency)}</span><div class="inline-actions"><button class="view-btn" data-action="account-ledger" data-id="${a.id}">ریزگردش</button><button class="view-btn" data-action="edit-account" data-id="${a.id}">ویرایش</button><button class="view-btn" data-action="delete-account" data-id="${a.id}">حذف</button></div></div></section>`).join(''):empty('حسابی موجود نیست','برای شروع، حداقل یک حساب اضافه کن.','new-account','افزودن حساب')}</div>`}
function filterActivities(){return activityRows().filter(t=>{const f=state.filter;const q=f.q.trim().toLocaleLowerCase('fa');let accountMatch=f.account==='all'||t.accountId===f.account||t.fromAccountId===f.account||t.toAccountId===f.account;let text=[t.party,t.category,t.note,t.description,accountName(t.accountId),accountName(t.fromAccountId),accountName(t.toAccountId),typeLabel(t.type)].join(' ').toLocaleLowerCase('fa');return (!q||text.includes(q))&&(f.type==='all'||(f.type==='settlements'?t.kind==='settlement':t.type===f.type))&&accountMatch&&(!f.from||t.date>=f.from)&&(!f.to||t.date<=f.to)})}
function renderTransactions(){const rows=filterActivities();return `<div class="section-heading"><div><h3>دفتر کامل تراکنش‌ها</h3><p>تمام دریافتی‌ها، پرداخت‌ها، انتقال‌ها و تسویه‌ها.</p></div><button class="btn primary" data-action="new-tx">${icon('plus')} ثبت تراکنش</button></div><section class="panel"><div class="flex-between"><span class="pill accent">${money(rows.length)} رویداد</span><button class="btn sm" data-action="csv">${icon('download',15)} خروجی CSV از فیلتر فعلی</button></div><div class="table-tools"><input class="field" data-filter="q" value="${esc(state.filter.q)}" placeholder="جست‌وجوی توضیح، شخص، دسته..."/><select class="select" data-filter="type"><option value="all">همه نوع تراکنش‌ها</option>${Object.entries(TX_TYPES).map(([k,v])=>`<option value="${k}" ${state.filter.type===k?'selected':''}>${v}</option>`).join('')}<option value="settlements" ${state.filter.type==='settlements'?'selected':''}>تسویه بدهی و طلب</option></select><select class="select" data-filter="account"><option value="all">تمام حساب‌ها</option>${ws().accounts.map(a=>`<option value="${a.id}" ${state.filter.account===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select><label class="form-group"><span class="form-label">از تاریخ میلادی</span><input type="date" class="field" data-filter="from" value="${esc(state.filter.from)}"/></label><label class="form-group"><span class="form-label">تا تاریخ میلادی</span><input type="date" class="field" data-filter="to" value="${esc(state.filter.to)}"/></label></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>تاریخ (شمسی)</th><th>نوع</th><th>دسته / مخاطب</th><th>حساب</th><th>مبلغ</th><th>جزئیات</th><th>عملیات</th></tr></thead><tbody>${rows.map(t=>{const curr=t.type==='transfer'?findAccount(t.fromAccountId)?.currency:findAccount(t.accountId)?.currency;const cur=curr||'IRT';return `<tr><td>${fmtDate(t.date)}${t.time?`<div class="tiny muted" dir="ltr">${esc(t.time)}</div>`:''}</td><td><span class="type-indicator ${typeColor(t.type)}">${typeLabel(t.type)}</span></td><td>${esc(t.category||t.party||'—')} ${t.receipt?icon('receipt',13):''}</td><td>${esc(t.type==='transfer'?accountName(t.fromAccountId)+' ← '+accountName(t.toAccountId):accountName(t.accountId))}</td><td class="${typeColor(t.type)}" dir="ltr" style="text-align:right">${money(t.amount,cur)} ${CURRENCIES[cur]}${t.type==='transfer'&&(t.receivedAmount!==t.amount||cur!==findAccount(t.toAccountId)?.currency)?` ⇐ ${money(t.receivedAmount,findAccount(t.toAccountId)?.currency)} ${esc(CURRENCIES[findAccount(t.toAccountId)?.currency]||'')}`:''}</td><td title="${esc(t.note||'')}">${esc((t.party||t.note||'—').slice(0,42))}</td><td><div class="table-actions">${t.receipt?`<button class="view-btn" data-action="receipt" data-id="${t.id}" title="رسید">رسید</button>`:''}${t.kind==='settlement'?`<button class="view-btn" data-action="nav" data-page="debts">بدهی‌ها</button>`:t.kind==='check'?`<button class="view-btn" data-action="nav" data-page="checks">چک‌ها</button>`:t.sourceDebtId?`<button class="view-btn" data-action="nav" data-page="debts">بدهی مربوط</button>`:`<button class="view-btn" data-action="edit-tx" data-id="${t.id}">ویرایش</button><button class="view-btn" data-action="delete-tx" data-id="${t.id}">حذف</button>`}</div></td></tr>`}).join('')}</tbody></table></div>`:empty('موردی پیدا نشد','اگر فیلتر گذاشتی، آن را تغییر بده یا تراکنش جدیدی ثبت کن.','new-tx','تراکنش جدید')}</section>`}
function renderDebts(){const list=ws().debts.filter(d=>state.debtFilter==='all'||d.direction===state.debtFilter);const isPast=d=>d.dueDate&&d.dueDate<today()&&remaining(d)>0;return `<div class="section-heading"><div><h3>مدیریت طلب‌ها و بدهی‌ها</h3><p>مانده، سررسید و تسویه هر شخص، مستقل از درآمد و هزینه.</p></div><button class="btn primary" data-action="new-debt">${icon('plus')} ثبت مورد</button></div><div class="section-note">${icon('info')}برای طلب یا بدهی تازه، حسابِ گردش اولیه را (در صورت وجود) انتخاب کن. هر پرداخت یا وصول ثبت‌شده بلافاصله در موجودی حساب و گردش مالی اعمال می‌شود، نه در سود و زیان. چک‌های مرتبط هنگام پاس‌شدن فقط یک‌بار تسویه می‌شوند.</div><div class="section-heading"><div class="pills"><button class="btn sm ${state.debtFilter==='all'?'primary':''}" data-action="debt-filter" data-value="all">همه</button><button class="btn sm ${state.debtFilter==='receivable'?'primary':''}" data-action="debt-filter" data-value="receivable">طلب‌ها</button><button class="btn sm ${state.debtFilter==='payable'?'primary':''}" data-action="debt-filter" data-value="payable">بدهی‌ها</button></div><span class="muted tiny">${money(list.length)} مورد</span></div><div class="grid-stats" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))">${list.length?list.map(d=>`<section class="debt-card"><div class="flex-between"><div class="item-title">${esc(d.person)}</div><span class="pill ${d.direction==='receivable'?'accent':''}">${d.direction==='receivable'?'طلب از شخص':'بدهی به شخص'}</span></div><div class="muted tiny">مبلغ اولیه: ${money(d.amount,d.currency)} ${CURRENCIES[d.currency]}</div><div class="debt-amount ${d.direction==='receivable'?'color-green':'color-red'}">${money(remaining(d),d.currency)} <span class="muted tiny">${CURRENCIES[d.currency]} مانده</span></div><div class="muted tiny debt-due ${isPast(d)?'overdue':''}">${d.dueDate?'سررسید: '+fmtDate(d.dueDate):'بدون سررسید'} ${isPast(d)?' · سررسید گذشته':''}</div><div class="muted tiny">تسویه‌شده: ${money(debtPaid(d),d.currency)} ${CURRENCIES[d.currency]}</div>${installmentSchedule(d).length?`<details class="v24-installments"><summary>برنامه اقساط (${installmentSchedule(d).filter(q=>q.remaining===0).length} از ${installmentSchedule(d).length} پرداخت‌شده)</summary>${installmentSchedule(d).map(q=>`<div class="v24-installment"><span>قسط ${q.number} · ${fmtDate(q.date)}</span><span class="${q.remaining&&q.date<today()?'color-red':''}">${money(q.remaining,d.currency)} ${CURRENCIES[d.currency]} مانده</span></div>`).join('')}</details>`:''}${d.note?`<div class="subtle tiny" style="margin-top:6px">${esc(d.note)}</div>`:''}<div class="debt-actions">${remaining(d)>0?`<button class="btn sm primary" data-action="settle" data-id="${d.id}">${icon('check',13)} ثبت تسویه</button>`:''}<button class="btn sm ghost" data-action="edit-debt" data-id="${d.id}">ویرایش</button><button class="btn sm ghost danger" data-action="delete-debt" data-id="${d.id}">حذف</button></div>${(d.settlements||[]).length?`<details style="margin-top:11px"><summary class="tiny muted" style="cursor:pointer">سوابق ${d.settlements.length} پرداخت</summary>${d.settlements.map(s=>`<div class="category-row"><div class="item-info tiny">${fmtDate(s.date)} · ${esc(accountName(s.accountId))}</div><div class="tiny">${money(s.amount,d.currency)}</div><button class="view-btn" data-action="delete-settlement" data-id="${d.id}" data-sub="${s.id}">حذف</button></div>`).join('')}</details>`:''}</section>`).join(''):empty('هنوز بدهی یا طلبی ثبت نشده','افراد، مبالغ، سررسیدها و تسویه‌ها را اینجا مدیریت کن.','new-debt','ثبت بدهی یا طلب')}</div>`}
function spendByCategory(month,cur){const obj={};for(const t of ws().transactions){const a=findAccount(t.accountId);if(t.type==='expense'&&jalaliKey(t.date)===month&&a?.currency===cur){const cat=t.category||'بدون دسته';obj[cat]=(obj[cat]||0)+t.amount}}return Object.entries(obj).sort((a,b)=>b[1]-a[1])}
function renderReports(){const cur=ws().reportCurrency,month=state.reportMonth,s=monthSummary(month,cur),spends=spendByCategory(month,cur),max=Math.max(1,...spends.map(x=>x[1]));return `<div class="section-heading"><div><h3>تحلیل مالی و بودجه‌بندی</h3><p>گزارش درآمد، هزینه و گردش نقدی با امکان چاپ.</p></div><div class="toolbar"><button class="btn sm" data-action="print">${icon('print',15)} چاپ / PDF</button></div></div><div class="panel"><div class="form-grid"><label class="form-group"><span class="form-label">ماه گزارش (شمسی)</span><select class="select" data-action-change="report-month">${recentMonths(120).reverse().map(m=>`<option value="${m}" ${month===m?'selected':''}>${fmtMonth(m)}</option>`).join('')}</select></label><label class="form-group"><span class="form-label">ارز گزارش</span><select class="select" data-action-change="currency">${currencyOptions(cur)}</select></label></div><p class="muted tiny" style="margin-top:10px">ماه انتخاب‌شده: ${esc(fmtMonth(month))} · ارزها عمداً با هم جمع نمی‌شوند.</p></div><div class="grid-stats spaced">${stat('درآمد ماه',s.income,cur,'income','color-green')}${stat('هزینه ماه',s.expense,cur,'expense','color-red')}${stat('سود / مازاد ماه',s.net,cur,'reports',s.net>=0?'color-green':'color-red')}${stat('تغییر جریان نقدی',s.cashFlow,cur,'wallets',s.cashFlow>=0?'color-accent':'color-red','شامل گردش سرمایه و تسویه‌ها، بدون انتقال')}</div><div class="columns-even spaced"><section class="panel"><div class="split-title"><h3>هزینه‌ها به تفکیک دسته</h3><span class="pill">${CURRENCIES[cur]}</span></div>${spends.length?spends.map(([c,n])=>`<div class="budget-row"><div class="flex-between"><span>${esc(c)}</span><b>${money(n,cur)}</b></div><div class="progress-track"><div class="progress-fill" style="width:${Math.max(1,n/max*100)}%"></div></div></div>`).join(''):empty('هزینه‌ای برای این ماه نیست','برای نمایش تحلیل هزینه، تراکنش هزینه ثبت کن.')}</section><section class="panel"><div class="split-title"><div><h3>بودجه‌های ماهانه</h3><p class="panel-sub">سقف هزینه برای هر دسته</p></div><button class="btn sm" data-action="new-budget">${icon('plus',14)} افزودن</button></div>${ws().budgets.filter(b=>b.currency===cur).length?ws().budgets.filter(b=>b.currency===cur).map(b=>{const used=spends.find(x=>x[0]===b.category)?.[1]||0,rate=Math.min(100,used/b.limit*100);return `<div class="budget-row"><div class="flex-between"><b>${esc(b.category)}</b><div class="inline-actions"><span class="muted tiny">${money(used,cur)} / ${money(b.limit,cur)}</span><button class="view-btn" data-action="edit-budget" data-id="${b.id}">ویرایش</button><button class="view-btn" data-action="delete-budget" data-id="${b.id}">حذف</button></div></div><div class="progress-track"><div class="progress-fill ${used>b.limit?'over':''}" style="width:${Math.max(1,rate)}%"></div></div><p class="tiny ${used>b.limit?'color-red':'muted'}">${used>b.limit?'بیش از سقف تعیین‌شده':`${money(Math.max(0,b.limit-used),cur)} ${CURRENCIES[cur]} باقی‌مانده`}</p></div>`}).join(''):empty('بودجه‌ای تعیین نشده','برای دسته‌های هزینه سقف ماهانه تعریف کن.','new-budget','تعیین بودجه')}</section></div><section class="panel spaced"><div class="split-title"><h3>نمودار شش‌ماهه</h3><span class="panel-sub">${CURRENCIES[cur]}</span></div>${chartMonths(cur)}</section>${renderV24Insights(cur,month,s)}`}
/* Hesabyar 2.4: check settlement, linked receivables, installments, recurring items, savings goals. */
function pageIntro(title,description,button,action){return `<div class="section-heading"><div><h3>${title}</h3><p>${description}</p></div><button class="btn primary" data-action="${action}">${icon('plus',17)} ${button}</button></div>`;}
function accountLedgerModal(id){const a=findAccount(id);if(!a)return;const movements=accountMovements(id),balance=accountBalances().get(id)||0;const body=`<div class="v24-overview"><div>موجودی محاسبه‌شده</div><strong>${money(balance,a.currency)} ${CURRENCIES[a.currency]}</strong><small>موجودی اولیه: ${money(a.openingBalance,a.currency)} + خالص گردش‌ها</small></div><div class="v24-list"><div class="v24-row"><span>موجودی اولیه</span><b>${money(a.openingBalance,a.currency)}</b></div>${movements.length?movements.slice(0,150).map(m=>`<div class="v24-row"><div><b>${esc(m.label)}</b><small>${fmtDate(m.date)}</small></div><b class="${m.amount<0?'color-red':'color-green'}" dir="ltr">${m.amount<0?'−':'+'}${money(Math.abs(m.amount),a.currency)}</b></div>`).join(''):`<p class="muted">گردشی ثبت نشده است.</p>`}</div><p class="form-help">تمام وصول و پرداخت‌های طلب و بدهی، و چک‌هایی که پاس شده‌اند، در این گردش نمایش داده می‌شوند.</p>`;showModal('ریزگردش · '+a.name,body);}
function renderDashboardV24(){const cur=ws().reportCurrency,upcoming=(ws().checks||[]).filter(c=>c.status==='pending'&&c.dueDate<=addDays(today(),10)).length,due=(ws().debts||[]).filter(d=>remaining(d)>0&&d.dueDate&&d.dueDate<today()).length;return `<div class="v24-quick-grid spaced"><button class="v24-quick" data-action="nav" data-page="checks"><span>${icon('receipt',22)}</span><strong>${upcoming} چک نیازمند پیگیری</strong><small>سررسید گذشته یا تا ۱۰ روز آینده</small></button><button class="v24-quick" data-action="nav" data-page="debts"><span>${icon('debts',22)}</span><strong>${due} بدهی/طلب سررسیدگذشته</strong><small>تسویه‌ها مستقیماً در موجودی حساب محاسبه می‌شوند</small></button><button class="v24-quick" data-action="nav" data-page="goals"><span>${icon('chart',22)}</span><strong>${(ws().goals||[]).length} هدف پس‌انداز</strong><small>پیشرفت برنامه‌های پس‌انداز</small></button></div>`;}
const addDays=(date,days)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+days);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
function renderChecks(){const all=ws().checks||[],items=all.filter(c=>state.checkFilter==='all'||c.status===state.checkFilter),due=all.filter(c=>c.status==='pending'&&c.dueDate<=today());return `${pageIntro('مدیریت چک‌ها','چک‌های دریافتی و پرداختی را پیگیری کن؛ موجودی فقط هنگام وصول یا پاس‌شدن تغییر می‌کند.','ثبت چک','new-check')}<div class="section-note">${icon('info')} چک «در انتظار» اثری روی موجودی ندارد. چک وصول‌شده، فقط یک بار در حساب ثبت می‌شود؛ اگر به طلب یا بدهی متصل باشد، تسویه همان مورد هم خودکار انجام می‌شود.</div><div class="v24-summary"><div><small>کل چک‌ها</small><b>${all.length}</b></div><div><small>در انتظار</small><b>${all.filter(c=>c.status==='pending').length}</b></div><div><small>سررسیدرسیده</small><b class="${due.length?'color-red':''}">${due.length}</b></div><div><small>وصول/پاس‌شده</small><b>${all.filter(c=>c.status==='cleared').length}</b></div></div><div class="pills spaced">${[['all','همه'],['pending','در انتظار'],['cleared','پاس‌شده'],['bounced','برگشتی'],['cancelled','باطل‌شده']].map(([k,l])=>`<button class="btn sm ${state.checkFilter===k?'primary':''}" data-action="check-filter" data-value="${k}">${l}</button>`).join('')}</div><div class="v24-cards">${items.length?items.slice().sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).map(c=>{const linked=ws().debts.find(d=>d.id===c.debtId);const canEdit=c.status!=='cleared';return `<section class="panel v24-item"><div class="flex-between"><span class="pill ${c.status==='cleared'?'accent':''}">${CHECK_STATUSES[c.status]||'در انتظار'}</span><strong>${c.direction==='incoming'?'چک دریافتی':'چک پرداختی'}</strong></div><div class="v24-main-amount ${c.direction==='incoming'?'color-green':'color-red'}">${money(c.amount,c.currency)} <small>${CURRENCIES[c.currency]}</small></div><h4>${esc(c.party)} <span class="muted">· ${esc(c.number)}</span></h4><div class="v24-meta"><span>بانک: ${esc(c.bank||'—')}</span><span>صدور: ${fmtDate(c.issueDate)}</span><span>سررسید: ${fmtDate(c.dueDate)}</span><span>حساب: ${esc(accountName(c.accountId))}</span>${linked?`<span>متصل به ${linked.direction==='receivable'?'طلب':'بدهی'}: ${esc(linked.person)}</span>`:''}</div>${(c.imageFront||c.imageBack)?`<div class="check-image-badges">${c.imageFront?`<button type="button" class="btn sm secondary" data-action="check-image-preview" data-id="${c.id}" data-side="front">${icon('image',15)} تصویر روی چک</button>`:''}${c.imageBack?`<button type="button" class="btn sm secondary" data-action="check-image-preview" data-id="${c.id}" data-side="back">${icon('image',15)} تصویر پشت چک</button>`:''}</div>`:''}${c.notes?`<p class="muted tiny">${esc(c.notes)}</p>`:''}${c.status==='cleared'?`<p class="tiny color-green">${icon('check',14)} تاریخ پاس‌شدن: ${fmtDate(c.clearedDate)} · ثبت مالی انجام شده</p>`:''}${c.status==='pending'&&c.dueDate<today()?`<p class="tiny color-red">سررسید گذشته است</p>`:''}<div class="v24-actions">${canEdit?`<button class="btn sm primary" data-action="clear-check" data-id="${c.id}">${icon('check',14)} ${c.direction==='incoming'?'ثبت وصول':'ثبت پاس‌شدن'}</button>`:''}${canEdit?`<button class="btn sm" data-action="edit-check" data-id="${c.id}">ویرایش</button>`:''}${c.status==='pending'?`<button class="btn sm" data-action="check-status" data-id="${c.id}" data-status="bounced">برگشتی</button><button class="btn sm" data-action="check-status" data-id="${c.id}" data-status="cancelled">ابطال</button>`:''}${c.status!=='pending'?`<button class="btn sm" data-action="check-status" data-id="${c.id}" data-status="pending">بازگشت به انتظار</button>`:''}${canEdit?`<button class="btn sm ghost danger" data-action="delete-check" data-id="${c.id}">حذف</button>`:''}</div></section>`;}).join(''):empty('چکی وجود ندارد','چک‌های دریافتی یا پرداختی را از این بخش ثبت کن.','new-check','ثبت چک')}</div>`;}

function safeCheckImage(img){return img?.data&&/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(img.data);}
function checkImageField(c,side){const img=side==='front'?c?.imageFront:c?.imageBack;const name=side==='front'?'روی چک':'پشت چک';return `<div class="form-group wide check-image-field" data-check-side="${side}"><span class="form-label">تصویر ${name} (اختیاری؛ JPEG / PNG / WebP تا ۲ مگابایت)</span><input class="field" type="file" accept="image/jpeg,image/png,image/webp" name="${side==='front'?'checkFrontFile':'checkBackFile'}" aria-label="انتخاب تصویر ${name}"/><small class="muted check-image-filename"></small>${safeCheckImage(img)?`<div class="check-image-existing"><img src="${esc(img.data)}" alt="تصویر ${name}" loading="lazy"/><span>${esc(img.name||name)}</span><button class="btn sm secondary" type="button" data-action="remove-check-image" data-side="${side}">حذف تصویر قبلی</button></div>`:''}</div>`;}
async function processCheckImage(file){if(!file)return null;if(file.size>2*1024*1024)throw Error('اندازه هر تصویر چک باید حداکثر ۲ مگابایت باشد.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('برای تصویر چک فقط JPEG، PNG و WebP مجاز است.');return await processReceipt(file);}
function previewCheckImage(id,side){const c=ws().checks.find(x=>x.id===id),img=side==='back'?c?.imageBack:c?.imageFront;if(!safeCheckImage(img))throw Error('تصویر معتبری برای این چک وجود ندارد.');const root=document.getElementById('check-image-root');root.innerHTML=`<div class="check-image-overlay" role="dialog" aria-modal="true" aria-label="تصویر چک"><div class="check-image-dialog"><div class="flex-between"><b>${side==='back'?'تصویر پشت چک':'تصویر روی چک'} · ${esc(c.number)}</b><button type="button" class="btn sm secondary" data-action="close-check-image">بستن</button></div><img src="${esc(img.data)}" alt="تصویر چک ${esc(c.number)}"/><p class="muted tiny">این تصویر تنها در مرورگر و فایل پشتیبان شما نگهداری می‌شود.</p></div></div>`;}

function checkModal(id){state.checkImagesRemoved={front:false,back:false};const c=(ws().checks||[]).find(x=>x.id===id);if(c?.status==='cleared')throw Error('برای ویرایش چک وصول‌شده ابتدا آن را به انتظار برگردان.');if(!ws().accounts.length){toast('ابتدا حساب بانکی/کیف پول بساز.');accountModal();return;}const accountId=c?.accountId||ws().accounts[0].id;const debtOptions=ws().debts.filter(d=>remaining(d)>0||d.id===c?.debtId).map(d=>`<option value="${d.id}" ${d.id===c?.debtId?'selected':''}>${d.direction==='receivable'?'طلب':'بدهی'} · ${esc(d.person)} · ${money(remaining(d),d.currency)} ${CURRENCIES[d.currency]}</option>`).join('');const body=`<input type="hidden" name="id" value="${c?.id||''}"/><div class="form-grid">${f('نوع چک','direction',`<select class="select" name="direction"><option value="incoming" ${c?.direction==='incoming'?'selected':''}>دریافتی</option><option value="outgoing" ${c?.direction==='outgoing'?'selected':''}>پرداختی</option></select>`)}${f('شماره چک','number',`<input class="field" name="number" required maxlength="70" value="${esc(c?.number||'')}"/>`)}${f('بانک صادرکننده','bank',`<input class="field" name="bank" maxlength="80" value="${esc(c?.bank||'')}"/>`)}${f('صادرکننده / دریافت‌کننده','party',`<input class="field" name="party" maxlength="100" required value="${esc(c?.party||'')}"/>`)}${f('حساب مالی','accountId',`<select class="select" name="accountId">${baseSelectAccounts(accountId)}</select>`,true,'بعد از وصول/پاس‌شدن، موجودی همین حساب تغییر می‌کند. ارز چک از ارز حساب گرفته می‌شود.')}${f('مبلغ','amount',`<input class="field" name="amount" required inputmode="decimal" value="${c?.amount||''}"/>`)}${checkJalaliField('issueDate',checkText('تاریخ صدور (شمسی)','Issue date (Jalali)'),c?.issueDate||today())}${checkJalaliField('dueDate',checkText('تاریخ سررسید (شمسی)','Due date (Jalali)'),c?.dueDate||today())}${f('اتصال به طلب/بدهی (اختیاری)','debtId',`<select class="select" name="debtId"><option value="">بدون اتصال</option>${debtOptions}</select>`,true,'نوع و ارز بدهی باید با چک سازگار باشد. تسویه هنگام پاس‌شدن به شکل خودکار ثبت می‌شود.')}${f('طبقه‌بندی مالی برای چکِ بدون بدهی','treatment',`<select class="select" name="treatment"><option value="capital" ${(!c||c.treatment==='capital')?'selected':''}>گردش سرمایه (بدون سود و زیان)</option><option value="income" ${c?.treatment==='income'?'selected':''}>درآمد (برای چک دریافتی)</option><option value="expense" ${c?.treatment==='expense'?'selected':''}>هزینه (برای چک پرداختی)</option></select>`,true,'اگر چک به طلب یا بدهی مرتبط باشد، درآمد/هزینه دوباره ثبت نمی‌شود.')}${f('توضیحات','notes',`<textarea class="field" name="notes" maxlength="400">${esc(c?.notes||'')}</textarea>`,true)}${checkImageField(c,'front')}${checkImageField(c,'back')}</div>`;showModal(c?'ویرایش چک':'ثبت چک جدید',body,'check-form');}
function checkClearModal(id){const c=ws().checks.find(x=>x.id===id);if(!c||c.status==='cleared')return;const body=`<input type="hidden" name="id" value="${c.id}"/><div class="v24-overview"><div>${c.direction==='incoming'?'مبلغ وصولی':'مبلغ پرداختی'} · ${esc(c.party)}</div><strong>${money(c.amount,c.currency)} ${CURRENCIES[c.currency]}</strong><small>حساب: ${esc(accountName(c.accountId))}${c.debtId?' · تسویه بدهی/طلب مرتبط':''}</small></div><div class="form-grid">${checkJalaliField('clearedDate',checkText('تاریخ وصول / پاس‌شدن (شمسی)','Clearing date (Jalali)'),today())}</div><div class="section-note">${icon('info')} با ثبت این عملیات، موجودی حساب فوراً تغییر می‌کند. برای اصلاح، می‌توانی از مدیریت چک وضعیت را به «در انتظار» بازگردانی.</div>`;showModal(c.direction==='incoming'?'تأیید وصول چک':'تأیید پاس‌شدن چک',body,'check-clear-form','ثبت اثر مالی و تسویه');}
async function changeCheckStatus(id,status){const c=ws().checks.find(x=>x.id===id);if(!c||!['pending','bounced','cancelled'].includes(status)||c.status===status)return;if(c.status==='cleared'){if(!ask('بازگرداندن چک پاس‌شده، گردش مالی و تسویه مرتبط را معکوس می‌کند. ادامه می‌دهی؟'))return;if(c.debtId){const d=ws().debts.find(x=>x.id===c.debtId);if(d)d.settlements=d.settlements.filter(s=>s.checkId!==c.id);}}c.status=status;c.clearedDate='';await persist();renderShell();toast('وضعیت چک و مانده حساب به‌روزرسانی شد.');}
function renderRecurring(){const all=ws().recurring||[],due=all.filter(r=>r.nextDate<=today()).length;return `${pageIntro('تراکنش‌های دوره‌ای','حقوق، اجاره، اشتراک و پرداخت‌های ماهانه را یک‌بار تعریف کن و در سررسید ثبت کن.','برنامه دوره‌ای','new-recurring')}<div class="section-note">${icon('info')} برای جلوگیری از ثبت اشتباه، تراکنش‌ها خودکار از حساب کسر یا به آن اضافه نمی‌شوند. در هر سررسید روی «ثبت این دوره» بزن؛ هر دوره فقط یک بار قابل ثبت است.</div><div class="v24-summary"><div><small>برنامه‌های فعال</small><b>${all.length}</b></div><div><small>نیازمند ثبت</small><b class="${due?'color-red':''}">${due}</b></div></div><div class="v24-cards">${all.length?all.slice().sort((a,b)=>a.nextDate.localeCompare(b.nextDate)).map(r=>`<section class="panel v24-item"><div class="flex-between"><span class="pill ${r.nextDate<=today()?'':'accent'}">${r.nextDate<=today()?'آماده ثبت':'در انتظار سررسید'}</span><span>${r.type==='income'?'درآمد دوره‌ای':'هزینه دوره‌ای'}</span></div><div class="v24-main-amount">${money(r.amount,r.currency)} <small>${CURRENCIES[r.currency]}</small></div><h4>${esc(r.title)}</h4><div class="v24-meta"><span>تکرار: ماهانه</span><span>نوبت بعدی: ${fmtDate(r.nextDate)}</span><span>حساب: ${esc(accountName(r.accountId))}</span></div><div class="v24-actions"><button class="btn sm primary" data-action="post-recurring" data-id="${r.id}" ${r.nextDate>today()?'disabled':''}>${icon('check',14)} ثبت این دوره</button><button class="btn sm" data-action="edit-recurring" data-id="${r.id}">ویرایش</button><button class="btn sm ghost danger" data-action="delete-recurring" data-id="${r.id}">حذف</button></div></section>`).join(''):empty('برنامه دوره‌ای نداری','برای پرداخت‌ها و درآمدهای تکراری یک برنامه بساز.','new-recurring','برنامه جدید')}</div>`;}
function recurringModal(id){const r=(ws().recurring||[]).find(x=>x.id===id);if(!ws().accounts.length){toast('ابتدا حساب ایجاد کن.');accountModal();return;}const type=r?.type||'expense';const cats=ws().categories[type]||[];const body=`<input type="hidden" name="id" value="${r?.id||''}"/><div class="form-grid">${f('نام برنامه','title',`<input class="field" name="title" maxlength="80" required value="${esc(r?.title||'')}" placeholder="مثلاً اجاره ماهانه"/>`)}${f('نوع','type',`<select class="select" name="type" id="recurring-type"><option value="expense" ${type==='expense'?'selected':''}>هزینه</option><option value="income" ${type==='income'?'selected':''}>درآمد</option></select>`)}${f('حساب','accountId',`<select class="select" name="accountId">${baseSelectAccounts(r?.accountId||ws().accounts[0].id)}</select>`)}${f('مبلغ ثابت','amount',`<input class="field" name="amount" inputmode="decimal" required value="${r?.amount||''}"/>`)}${f('تاریخ اولین/بعدی ثبت','nextDate',`<input class="field" name="nextDate" type="date" required value="${r?.nextDate||today()}"/>`,false,'ماهانه تکرار می‌شود؛ ثبت فقط با تأیید شما انجام خواهد شد.')}${f('دسته‌بندی','category',`<select class="select" name="category" id="recurring-category">${cats.map(x=>`<option value="${esc(x)}" ${r?.category===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`)}${f('توضیحات','note',`<textarea class="field" name="note" maxlength="300">${esc(r?.note||'')}</textarea>`,true)}</div>`;showModal(r?'ویرایش برنامه ماهانه':'تعریف تراکنش دوره‌ای',body,'recurring-form');}
async function postRecurring(id){const r=ws().recurring.find(x=>x.id===id);if(!r)return;if(r.nextDate>today())throw Error('سررسید این دوره هنوز نرسیده است.');const a=findAccount(r.accountId);if(!a||a.currency!==r.currency)throw Error('حساب برنامه حذف شده یا ارز آن تغییر کرده است.');if(ws().transactions.some(t=>t.recurringId===r.id&&t.cycleDate===r.nextDate))throw Error('این نوبت قبلاً ثبت شده؛ تاریخ دوره بعدی را بررسی کن.');const cycle=r.nextDate;ws().transactions.push({id:uid(),recurringId:r.id,cycleDate:cycle,type:r.type,amount:r.amount,accountId:r.accountId,date:cycle,time:currentTime(),category:r.category||'',note:r.note||'تراکنش دوره‌ای',party:r.title,createdAt:new Date().toISOString()});r.nextDate=addMonthsAnchored(cycle,r.anchorDay||Number(cycle.slice(-2)));await persist();renderShell();toast('تراکنش این ماه فقط یک‌بار ثبت شد و موجودی حساب تغییر کرد.');}
/* Savings goals 2.4.3: explicit journal + opt-in real account transfers + charts.
   Old g.saved is retained as the legacy opening amount and is never discarded. */
function goalHistory(g){const manual=(g.movements||[]).map(m=>({id:m.id,date:m.date,amount:Number(m.amount)||0,method:'manual',note:m.note||''}));const bank=ws().transactions.filter(t=>t.goalId===g.id&&t.type==='transfer').map(t=>({id:t.id,date:t.date,amount:t.goalDirection==='withdraw'?-Number(t.amount):Number(t.receivedAmount??t.amount),method:'transfer',note:t.note||'',fromAccountId:t.fromAccountId,toAccountId:t.toAccountId}));return [...manual,...bank].sort((a,b)=>(b.date||'').localeCompare(a.date||''));}
function goalSaved(g){const opening=Number(g.saved)||0;return roundCur(opening+goalHistory(g).reduce((s,m)=>s+(Number(m.amount)||0),0),g.currency);}
function goalAccounts(g){return ws().accounts.filter(a=>a.currency===g.currency);}
function goalTimeline(g){const history=goalHistory(g).slice().sort((a,b)=>(a.date||'').localeCompare(b.date||'')||(a.id||'').localeCompare(b.id||''));const startDate=g.createdAt?.slice?.(0,10)||history[0]?.date||today();let total=roundCur(Number(g.saved)||0,g.currency);const points=[{date:startDate,value:Math.max(0,total),delta:0}];for(const h of history){total=roundCur(total+(Number(h.amount)||0),g.currency);points.push({date:h.date||startDate,value:Math.max(0,total),delta:Number(h.amount)||0});}return points;}
function goalTrendChart(g){const points=goalTimeline(g),target=Math.max(0,Number(g.target)||0),current=Math.max(0,goalSaved(g)),peak=Math.max(1,target,current,...points.map(p=>p.value));const w=320,h=118,p=12,iw=w-p*2,ih=h-p*2;const linePts=points.map((pt,i)=>{const x=p+(points.length===1?iw/2:(i/(points.length-1))*iw);const y=h-p-(pt.value/peak)*ih;return [x,y];});const path=linePts.map((q,i)=>`${i?'L':'M'}${q[0].toFixed(1)},${q[1].toFixed(1)}`).join(' ');const area=`M${linePts[0][0].toFixed(1)},${(h-p).toFixed(1)} `+linePts.map(q=>`L${q[0].toFixed(1)},${q[1].toFixed(1)}`).join(' ')+` L${linePts[linePts.length-1][0].toFixed(1)},${(h-p).toFixed(1)} Z`;const targetY=target>0?(h-p-(Math.min(target,peak)/peak)*ih):null;const grid=[0.25,0.5,0.75].map(r=>{const y=(h-p-r*ih).toFixed(1);return `<line x1="${p}" y1="${y}" x2="${w-p}" y2="${y}" class="goal-chart-grid"/>`;}).join('');const dots=linePts.map((q,i)=>`<circle cx="${q[0].toFixed(1)}" cy="${q[1].toFixed(1)}" r="${i===linePts.length-1?3.9:2.6}" class="goal-chart-dot ${i===linePts.length-1?'current':''}"/>`).join('');return `<div class="goal-chart-box"><div class="goal-chart-top"><b>نمودار روند پس‌انداز</b><span>${points.length-1?`${points.length-1} ثبت`:'بدون سابقه'}</span></div><svg class="goal-chart-svg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-label="نمودار روند هدف">${grid}${targetY!==null?`<line x1="${p}" y1="${targetY.toFixed(1)}" x2="${w-p}" y2="${targetY.toFixed(1)}" class="goal-chart-target"/>`:''}<path d="${area}" class="goal-chart-area"/><path d="${path}" class="goal-chart-line"/>${dots}</svg><div class="goal-chart-meta"><span><i class="goal-swatch trend"></i>مانده فعلی</span><span>${target>0?'<i class="goal-swatch target"></i>خط هدف':'بدون مبلغ هدف'}</span></div></div>`;}
function goalsOverview(goals){const rows=goals.map(g=>{const amount=goalSaved(g),target=Math.max(0,Number(g.target)||0),percent=target>0?Math.max(0,Math.min(100,amount/target*100)):0;return {id:g.id,title:g.title,currency:g.currency,target,amount,percent,dueDate:g.dueDate||''};});const completed=rows.filter(r=>r.target>0&&r.amount>=r.target).length,upcoming=rows.filter(r=>r.target>0&&r.amount<r.target&&r.dueDate&&r.dueDate<=addDays(today(),30)).length;return `<section class="panel goal-overview-panel"><div class="split-title"><div><p class="eyebrow">نمای کلی هدف‌ها</p><h3>وضعیت کلی پس‌اندازها</h3><p class="panel-sub">با یک نگاه ببین چند هدف تکمیل شده و هر هدف چقدر تا مقصد فاصله دارد.</p></div>${icon('chart',20)}</div><div class="goal-overview-stats"><div><small>کل هدف‌ها</small><b>${rows.length}</b></div><div><small>تکمیل‌شده</small><b class="color-green">${completed}</b></div><div><small>نزدیک سررسید</small><b class="${upcoming?'color-red':''}">${upcoming}</b></div></div><div class="goal-overview-bars">${rows.sort((a,b)=>b.percent-a.percent).slice(0,8).map(r=>`<div class="goal-overview-row"><div class="goal-overview-title"><b>${esc(r.title)}</b><span>${new Intl.NumberFormat(locale()==='en'?'en-US':'fa-IR',{maximumFractionDigits:1}).format(r.percent)}٪</span></div><div class="progress-track"><div class="progress-fill" style="width:${r.percent}%"></div></div><div class="goal-overview-caption"><span>${money(r.amount,r.currency)} ${esc(CURRENCIES[r.currency]||r.currency)}</span><span>از ${money(r.target,r.currency)} ${esc(CURRENCIES[r.currency]||r.currency)}</span></div></div>`).join('')}</div></section>`;}
function renderGoals(){const goals=ws().goals||[];return `${pageIntro('اهداف پس‌انداز','ثبت هدف، افزودن پس‌انداز، برداشت و نمودار روند رشد هر هدف.','هدف جدید','new-goal')}<div class="section-note">${icon('info')} ثبت دستی، فقط پیشرفت هدف را تغییر می‌دهد و روی مانده حساب بانکی اثری ندارد. برای جابه‌جایی واقعی، هنگام ثبت پس‌انداز گزینه «انتقال واقعی بین دو حساب» را انتخاب کن؛ موجودی دو حساب تغییر می‌کند اما درآمد یا هزینه محسوب نمی‌شود.</div>${goals.length?goalsOverview(goals):''}<div class="v24-cards">${goals.length?goals.map(g=>{const amount=goalSaved(g),target=Number(g.target)||0,percent=target>0?Math.max(0,Math.min(100,amount/target*100)):0,history=goalHistory(g);return `<section class="panel v24-item goal-card"><div class="goal-head"><span class="pill accent">${amount>=target&&target>0?'هدف تکمیل شده':'هدف پس‌انداز'}</span><span class="muted tiny">${g.dueDate?'تاریخ هدف: '+fmtDate(g.dueDate):'بدون سررسید'}</span></div><h4>${esc(g.title)}</h4><div class="v24-main-amount">${money(amount,g.currency)} <small>${esc(CURRENCIES[g.currency]||g.currency)}</small></div><div class="muted tiny">هدف: ${money(target,g.currency)} ${esc(CURRENCIES[g.currency]||g.currency)}</div><div class="progress-track" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent.toFixed(1)}"><div class="progress-fill" style="width:${percent}%"></div></div><div class="v24-meta"><span>${new Intl.NumberFormat(locale()==='en'?'en-US':'fa-IR',{maximumFractionDigits:1}).format(percent)}٪ تکمیل</span><span>${amount>=target&&target>0?'مبلغ هدف تأمین شده':money(Math.max(0,target-amount),g.currency)+' '+esc(CURRENCIES[g.currency]||g.currency)+' باقی‌مانده'}</span></div>${goalTrendChart(g)}<div class="v24-actions"><button class="btn sm primary" data-action="goal-adjust" data-kind="deposit" data-id="${esc(g.id)}">${icon('plus',14)} افزودن</button><button class="btn sm secondary" data-action="goal-adjust" data-kind="withdraw" data-id="${esc(g.id)}" ${amount<=0?'disabled':''}>${icon('minus',14)} برداشت</button><button class="btn sm ghost" data-action="edit-goal" data-id="${esc(g.id)}">ویرایش هدف</button><button class="btn sm ghost danger" data-action="delete-goal" data-id="${esc(g.id)}">حذف</button></div><details class="goal-history"><summary>تاریخچه پس‌انداز (${history.length} مورد)</summary>${Number(g.saved)>0?`<div class="v24-row"><div><b>مانده اولیه هدف</b><small>ثبت‌شده در نسخه قبلی / هنگام ایجاد</small></div><b class="color-green">+${money(g.saved,g.currency)}</b></div>`:''}${history.length?history.slice(0,80).map(h=>`<div class="v24-row"><div><b>${h.amount>=0?'افزودن پس‌انداز':'برداشت از پس‌انداز'}</b><small>${fmtDate(h.date)} · ${h.method==='transfer'?'انتقال بانکی':'ثبت دستی'}${h.note?' · '+esc(h.note):''}</small>${h.method==='transfer'?`<small>${esc(accountName(h.fromAccountId))} ← ${esc(accountName(h.toAccountId))}</small>`:''}</div><div class="goal-movement-side"><b class="${h.amount<0?'color-red':'color-green'}">${h.amount<0?'−':'+'}${money(Math.abs(h.amount),g.currency)}</b><button class="view-btn" data-action="goal-remove-move" data-id="${esc(g.id)}" data-sub="${esc(h.id)}" data-method="${h.method}">برگرداندن</button></div></div>`).join(''):'<p class="muted tiny">هنوز حرکتی ثبت نشده است.</p>'}</details></section>`;}).join(''):empty('هدفی ثبت نشده','یک هدف مالی مشخص کن؛ سپس با دکمه افزودن یا برداشت، پیشرفت آن را به‌روز کن.','new-goal','ساخت هدف')}</div>`;}
function goalModal(id){const g=(ws().goals||[]).find(x=>x.id===id);const used=!!g&&(goalSaved(g)!==0||(g.movements||[]).length>0||ws().transactions.some(t=>t.goalId===g.id));const body=`<input type="hidden" name="id" value="${esc(g?.id||'')}"/><div class="form-grid">${f('عنوان هدف','title',`<input class="field" name="title" required maxlength="80" value="${esc(g?.title||'')}" placeholder="مثلاً سرمایه خرید لپ‌تاپ"/>`,true)}${f('ارز','currency',`<select class="select" name="currency" ${used?'disabled':''}>${currencyOptions(g?.currency||ws().reportCurrency)}</select>${used?`<input type="hidden" name="currency" value="${esc(g.currency)}"/>`:''}`)}${f('مبلغ هدف','target',`<input class="field" name="target" inputmode="decimal" required value="${g?.target??''}"/>`)}${g?`<div class="form-group wide"><span class="form-label">پس‌انداز فعلی</span><strong>${money(goalSaved(g),g.currency)} ${esc(CURRENCIES[g.currency]||g.currency)}</strong><div class="form-help">برای افزودن یا برداشت مبلغ از دکمه‌های خود هدف استفاده کن. موجودی قبلی حفظ شده است.</div></div>`:f('موجودی اولیه پس‌انداز (اختیاری)','saved',`<input class="field" name="saved" inputmode="decimal" value="0"/>`,true,'این عدد فقط موجودی اولیه هدف است و از حساب بانکی کسر نمی‌شود.')}${f('تاریخ هدف (اختیاری)','dueDate',`<input class="field" name="dueDate" type="date" value="${esc(g?.dueDate||'')}"/>`)}</div>`;showModal(g?'ویرایش هدف پس‌انداز':'هدف مالی جدید',body,'goal-form');}
function goalMoveModal(id,kind){const g=(ws().goals||[]).find(x=>x.id===id);if(!g)return;const current=goalSaved(g),accounts=goalAccounts(g),hasTwo=accounts.length>=2,fromDefault=accounts[kind==='withdraw'?1:0]?.id,toDefault=accounts[kind==='withdraw'?0:1]?.id;const accountOptions=selected=>accounts.map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(a.name)} · ${money(accountBalances().get(a.id)||0,a.currency)} ${esc(CURRENCIES[a.currency])}</option>`).join('');const body=`<input type="hidden" name="goalId" value="${esc(g.id)}"/><input type="hidden" name="kind" value="${kind}"/><div class="v24-overview"><small>${esc(g.title)} · موجودی هدف</small><strong>${money(current,g.currency)} ${esc(CURRENCIES[g.currency])}</strong></div><div class="form-grid">${f('مبلغ '+(kind==='deposit'?'افزودن':'برداشت'),'amount',`<input class="field" name="amount" inputmode="decimal" required placeholder="مبلغ را وارد کن"/>`)}${f('تاریخ','date',`<input class="field" name="date" type="date" required value="${today()}"/>`)}${f('روش ثبت','booking',`<select class="select" name="booking" id="goal-booking"><option value="manual">ثبت دستی (بدون تغییر حساب)</option>${hasTwo?'<option value="transfer">انتقال واقعی بین دو حساب</option>':''}</select>`,true,'انتقال واقعی فقط با دو حساب هم‌ارز انجام می‌شود. پس‌انداز، درآمد یا هزینه جدید نیست.')}${hasTwo?`<div class="goal-transfer-fields form-group wide" id="goal-transfer-fields" hidden><div class="form-grid">${f('حساب مبدأ','fromAccountId',`<select class="select" name="fromAccountId">${accountOptions(fromDefault)}</select>`)}${f('حساب مقصد','toAccountId',`<select class="select" name="toAccountId">${accountOptions(toDefault)}</select>`)}</div><p class="form-help">${kind==='deposit'?'پول از حساب مبدأ به حساب پس‌انداز منتقل می‌شود.':'پول از حساب پس‌انداز به حساب مقصد برمی‌گردد.'} هر دو حساب باید ارز ${esc(CURRENCIES[g.currency])} داشته باشند.</p></div>`:''}${f('توضیحات (اختیاری)','note',`<textarea class="field" name="note" maxlength="180"></textarea>`,true)}</div>`;showModal(kind==='deposit'?'افزودن به پس‌انداز':'برداشت از پس‌انداز',body,'goal-move-form',kind==='deposit'?'ثبت پس‌انداز':'ثبت برداشت');}
async function removeGoalMovement(goalId,entryId,method){const w=ws(),g=w.goals.find(x=>x.id===goalId);if(!g)return;const entry=goalHistory(g).find(x=>x.id===entryId&&x.method===method);if(!entry)return;const amountAfter=roundCur(goalSaved(g)-entry.amount,g.currency);if(amountAfter<0)throw Error('این حذف، مانده پس‌انداز را منفی می‌کند. ابتدا برداشت‌های بعدی را برگردان.');if(!ask(method==='transfer'?'انتقال واقعی حذف شود؟ اثر آن از گردش حساب مبدأ و مقصد هم برگردانده می‌شود.':'ثبت دستی پس‌انداز حذف شود؟'))return;if(method==='transfer')w.transactions=w.transactions.filter(t=>t.id!==entryId);else g.movements=(g.movements||[]).filter(m=>m.id!==entryId);await persist();renderShell();toast('ثبت پس‌انداز و اثر مالی مرتبط برگردانده شد.');}
function renderV24Insights(cur,month,s){const dueList=[];for(const c of ws().checks||[])if(c.currency===cur&&c.status==='pending'&&c.dueDate<=addDays(today(),45))dueList.push({date:c.dueDate,label:'چک '+c.number+' · '+c.party,amount:c.amount});for(const d of ws().debts)if(d.currency===cur){const schedule=installmentSchedule(d);if(schedule.length){for(const q of schedule)if(q.remaining>0&&q.date<=addDays(today(),45))dueList.push({date:q.date,label:'قسط '+q.number+' · '+d.person,amount:q.remaining});}else if(remaining(d)>0&&d.dueDate&&d.dueDate<=addDays(today(),45))dueList.push({date:d.dueDate,label:(d.direction==='receivable'?'طلب':'بدهی')+' · '+d.person,amount:remaining(d)});}dueList.sort((a,b)=>a.date.localeCompare(b.date));const activeChecks=(ws().checks||[]).filter(c=>c.status==='cleared'&&!c.debtId&&c.currency===cur&&jalaliKey(c.clearedDate||c.dueDate)===month),inChecks=activeChecks.filter(c=>c.direction==='incoming').reduce((v,c)=>v+c.amount,0),outChecks=activeChecks.filter(c=>c.direction==='outgoing').reduce((v,c)=>v+c.amount,0);return `<div class="columns-even spaced"><section class="panel"><div class="split-title"><h3>جزئیات تسویه‌ها و چک‌ها</h3><span class="pill">${CURRENCIES[cur]}</span></div><div class="v24-row"><span>وصول طلب</span><b class="color-green">+${money(s.settleIn,cur)}</b></div><div class="v24-row"><span>پرداخت بدهی</span><b class="color-red">−${money(s.settleOut,cur)}</b></div><div class="v24-row"><span>چک دریافتی پاس‌شده (مستقل)</span><b class="color-green">+${money(inChecks,cur)}</b></div><div class="v24-row"><span>چک پرداختی پاس‌شده (مستقل)</span><b class="color-red">−${money(outChecks,cur)}</b></div><p class="form-help">چک متصل به بدهی فقط در ردیف تسویه شمرده می‌شود. همه ارقام به ارز انتخابی است.</p></section><section class="panel"><div class="split-title"><h3>سررسیدهای نزدیک و گذشته</h3><span class="pill">۴۵ روز آینده</span></div>${dueList.length?dueList.slice(0,9).map(q=>`<div class="v24-row"><div><b>${esc(q.label)}</b><small class="${q.date<today()?'color-red':''}">${fmtDate(q.date)} ${q.date<today()?' · گذشته':''}</small></div><b>${money(q.amount,cur)}</b></div>`).join(''):'<p class="muted">سررسید بازی در این بازه نیست.</p>'}</section></div>`;}
function encryptedBackupModal(){const body=`<p class="section-note">فایل پشتیبان با AES-GCM و گذرواژه‌ای که انتخاب می‌کنی رمزگذاری می‌شود. بدون این گذرواژه بازیابی ممکن نیست. داده‌های داخل خود مرورگر رمزگذاری نمی‌شوند.</p><div class="form-grid">${f('گذرواژه فایل (حداقل ۱۰ کاراکتر)','password',`<input class="field" type="password" autocomplete="new-password" required minlength="10" name="password"/>`,true)}${f('تکرار گذرواژه','repeat',`<input class="field" type="password" autocomplete="new-password" required minlength="10" name="repeat"/>`,true)}</div>`;showModal('پشتیبان رمزدار',body,'encrypted-backup-form','ساخت فایل رمزدار');}
const bytesToB64=bytes=>{let out='';for(let i=0;i<bytes.length;i+=16384)out+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(out);};
const b64ToBytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function encryptionKey(password,salt,usage){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,usage);}
async function encryptedBackup(password){if(!globalThis.crypto?.subtle)throw Error('پشتیبان رمزدار فقط روی HTTPS و مرورگر سازگار قابل ساخت است.');const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12));const key=await encryptionKey(password,salt,['encrypt']);const raw=new TextEncoder().encode(JSON.stringify(state.data));const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,raw);const payload={format:'hesabyar-encrypted-v1',algorithm:'AES-256-GCM',kdf:'PBKDF2-SHA256',iterations:210000,salt:bytesToB64(salt),iv:bytesToB64(iv),payload:bytesToB64(new Uint8Array(encrypted))};download(JSON.stringify(payload),`hesabyar-encrypted-backup-${today()}.json`,'application/json;charset=utf-8');state.data.settings.lastBackup=new Date().toISOString();await persist();toast('فایل رمزدار ساخته شد. گذرواژه را در محل مطمئن نگهداری کن.');}
async function decryptBackup(payload,password){if(!globalThis.crypto?.subtle)throw Error('مرورگر از رمزگشایی پشتیبانی نمی‌کند.');try{if(payload.algorithm!=='AES-256-GCM'||payload.kdf!=='PBKDF2-SHA256'||payload.iterations!==210000)throw Error('فرمت رمزگذاری نامعتبر است.');const key=await encryptionKey(password,b64ToBytes(payload.salt),['decrypt']);const raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(payload.iv)},key,b64ToBytes(payload.payload));return JSON.parse(new TextDecoder().decode(raw));}catch(e){throw Error('گذرواژه اشتباه است یا فایل آسیب دیده است.');}}


// Reminders are device-local. Browser alerts can only be shown while this page is open.
const REMINDER_CHOICES=[1,3,7,14,30];
function reminderItems(workspace=ws(),scope=state.workspace){
 const days=REMINDER_CHOICES.includes(Number(state.data?.settings?.reminderDays))?Number(state.data.settings.reminderDays):7;
 const max=addDays(today(),days),all=[];
 for(const c of workspace.checks||[]){if(c.status!=='pending'||!isISODate(c.dueDate)||c.dueDate>max)continue;
  all.push({key:scope+':check:'+c.id,type:'check',date:c.dueDate,id:c.id,label:'چک '+c.number+' · '+c.party,amount:c.amount,currency:c.currency,extra:c.direction==='incoming'?'دریافتی':'پرداختی'});
 }
 for(const d of workspace.debts||[]){if(remaining(d)<=0)continue;const schedule=installmentSchedule(d);
  if(schedule.length){for(const q of schedule){if(q.remaining<=0||!isISODate(q.date)||q.date>max)continue;all.push({key:scope+':installment:'+d.id+':'+q.number,type:'installment',date:q.date,id:d.id,label:'قسط '+q.number+' · '+d.person,amount:q.remaining,currency:d.currency,extra:d.direction==='payable'?'پرداختنی':'دریافتنی'});}}
  else if(d.dueDate&&isISODate(d.dueDate)&&d.dueDate<=max){all.push({key:scope+':debt:'+d.id,type:'debt',date:d.dueDate,id:d.id,label:(d.direction==='payable'?'بدهی':'طلب')+' · '+d.person,amount:remaining(d),currency:d.currency,extra:d.direction==='payable'?'پرداختنی':'دریافتنی'});}
 }
 return all.sort((a,b)=>a.date.localeCompare(b.date)||a.label.localeCompare(b.label));
}
function liveReminders(){const all=reminderItems();return state.reminderAll?all:all.filter(r=>state.data.settings.reminderSnoozed?.[r.key]!==today());}
function reminderBadge(){return reminderItems().filter(r=>state.data.settings.reminderSnoozed?.[r.key]!==today()).length;}
function renderReminders(){const all=reminderItems(),items=liveReminders(),overdue=all.filter(r=>r.date<today()).length,soon=all.filter(r=>r.date>=today()).length;
 return `<div class="section-heading"><div><p class="eyebrow">برنامه‌ریزی و پیگیری</p><h3>یادآور سررسیدها</h3><p>چک‌های در انتظار، اقساط تسویه‌نشده و بدهی‌های سررسیددار در دفتر فعال.</p></div></div>
 <div class="section-note">${icon('info',18)} یادآورها داخل برنامه نمایش داده می‌شوند. اعلان اختیاری مرورگر فقط هنگام باز بودن حساب‌یار و داشتن مجوز نمایش داده می‌شود؛ اعلان در زمان بسته بودن برنامه تضمین نمی‌شود.</div>
 <div class="v24-summary"><div><small>یادآورهای باز</small><b>${all.length}</b></div><div><small>عقب‌افتاده</small><b class="${overdue?'color-red':''}">${overdue}</b></div><div><small>امروز تا ${state.data.settings.reminderDays||7} روز آینده</small><b>${soon}</b></div></div>
 <div class="reminder-actions"><button class="btn secondary" data-action="reminder-toggle-all">${state.reminderAll?'مخفی‌کردن یادآورهای امروز':'نمایش همه (حتی یادآوری‌شده‌ها)'}</button><button class="btn secondary" data-action="nav" data-page="settings">تنظیم فاصله هشدار</button></div>
 <div class="v24-cards">${items.length?items.map(r=>`<article class="panel v24-item reminder-item"><div class="flex-between"><span class="pill ${r.date<today()?'due-over':''}">${r.date<today()?'عقب‌افتاده':r.date===today()?'امروز':'نزدیک'}</span><span class="muted tiny">${r.type==='check'?'چک':r.type==='installment'?'قسط':'بدهی/طلب'} · ${esc(r.extra)}</span></div><h4>${esc(r.label)}</h4><div class="v24-main-amount">${amountLabel(r.amount,r.currency)}</div><p class="muted">سررسید: ${fmtDate(r.date)}</p><div class="v24-actions"><button class="btn sm primary" data-action="reminder-open" data-type="${r.type}" data-id="${esc(r.id)}">${r.type==='check'?'مشاهده چک':'مشاهده بدهی / اقساط'}</button><button class="btn sm secondary" data-action="reminder-snooze" data-key="${esc(r.key)}">یادآوری فردا</button></div></article>`).join(''):empty('یادآور فعالی نیست','سررسید بازی در بازه انتخاب‌شده وجود ندارد.')}</div>`;
}
async function browserReminder(){if(state.locked||!state.data?.settings?.browserReminders||typeof Notification==='undefined'||Notification.permission!=='granted')return;
 const key=today()+':'+state.workspace;if(state.data.settings.lastBrowserReminder===key)return;
 const n=reminderItems().filter(x=>state.data.settings.reminderSnoozed?.[x.key]!==today()).length;
 if(!n)return;try{new Notification('حساب‌یار | یادآور مالی',{body:`${n} چک، قسط یا تعهد مالی نیازمند بررسی است.`,tag:'hesabyar-finance-due'});
 state.data.settings.lastBrowserReminder=key;await persist();}catch(e){console.warn('Browser reminder unavailable',e);}}
async function enableBrowserReminders(){if(typeof Notification==='undefined'||!globalThis.isSecureContext)throw Error('اعلان مرورگر فقط روی HTTPS و مرورگر سازگار پشتیبانی می‌شود.');
 const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('مجوز اعلان داده نشد؛ یادآورهای داخل برنامه همچنان فعال هستند.');state.data.settings.browserReminders=true;await persist();await browserReminder();renderShell();toast('اعلان مرورگر هنگام باز بودن برنامه فعال شد.');}

// Optional local UI lock: PIN is PBKDF2-verified, but the IndexedDB data itself is NOT encrypted.
const PIN_ITERATIONS=230000;
async function pinHash(pin,salt,iterations=PIN_ITERATIONS){if(!crypto?.subtle)throw Error('قفل PIN در این مرورگر یا اتصال قابل استفاده نیست.');
 const imported=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);
 return new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations,hash:'SHA-256'},imported,256));}
async function makePinRecord(pin){if(!/^\d{6,12}$/.test(pin))throw Error('PIN باید شامل ۶ تا ۱۲ رقم انگلیسی باشد.');const salt=crypto.getRandomValues(new Uint8Array(16));const hash=await pinHash(pin,salt);return {version:1,salt:bytesToB64(salt),hash:bytesToB64(hash),iterations:PIN_ITERATIONS};}
async function verifyPin(pin){const cfg=state.data?.settings?.pinLock;if(!cfg||!/^\d{6,12}$/.test(pin))return false;
 try{if(cfg.version!==1||!Number.isInteger(cfg.iterations)||cfg.iterations<100000||cfg.iterations>500000)return false;
 const got=await pinHash(pin,b64ToBytes(cfg.salt),cfg.iterations),wanted=b64ToBytes(cfg.hash);let diff=got.length^wanted.length;for(let i=0;i<got.length;i++)diff|=got[i]^(wanted[i]||0);return diff===0;}catch(e){return false;}}
function pinModal(mode='set'){const has=!!state.data.settings.pinLock;
 const body=`<div class="section-note">${icon('shield',18)} این قفل دسترسی معمول به صفحه برنامه را محدود می‌کند؛ داده‌های داخل مرورگر را رمزگذاری نمی‌کند. PIN را فراموش نکن و حتماً پشتیبان رمزدار تهیه کن.</div><div class="form-grid">
 ${has?f('PIN فعلی','oldPin',`<input class="field" name="oldPin" type="password" inputmode="numeric" autocomplete="off" pattern="[0-9]{6,12}" minlength="6" maxlength="12" required/>`,true):''}
 ${mode!=='disable'?f('PIN جدید (۶ تا ۱۲ رقم)','pin',`<input class="field" name="pin" type="password" inputmode="numeric" autocomplete="new-password" pattern="[0-9]{6,12}" minlength="6" maxlength="12" required/>`,true)+f('تکرار PIN','repeatPin',`<input class="field" name="repeatPin" type="password" inputmode="numeric" autocomplete="new-password" pattern="[0-9]{6,12}" minlength="6" maxlength="12" required/>`,true):''}
 </div>`;
 showModal(mode==='disable'?'غیرفعال‌کردن قفل PIN':has?'تغییر PIN برنامه':'فعال‌سازی قفل PIN',body,mode==='disable'?'pin-disable-form':'pin-set-form',mode==='disable'?'غیرفعال‌سازی قفل':'ذخیره PIN');}
function pinLockScreen(message=''){const root=document.getElementById('pin-lock-root');if(!root)return;document.body.classList.add('hy-pin-locked');
 root.innerHTML=`<div class="pin-lock-overlay"><div class="pin-lock-card" role="dialog" aria-modal="true" aria-labelledby="pin-lock-heading"><span class="pin-lock-icon">${icon('lock',34)}</span><span class="eyebrow">HESABYAR / PRIVACY LOCK</span><h2 id="pin-lock-heading">${gt('حساب‌یار قفل است','Hesabyar is locked')}</h2><p>${gt('برای مشاهده اطلاعات مالی PIN شخصی خودت را وارد کن.','Enter your PIN to view your finances.')}</p><form id="pin-unlock-form"><label class="form-group"><span class="form-label">${gt('PIN برنامه','App PIN')}</span><input class="field pin-unlock-input" name="pin" type="password" inputmode="numeric" autocomplete="off" pattern="[0-9]{6,12}" minlength="6" maxlength="12" required/></label><p class="pin-lock-error" role="status">${esc(message)}</p><button class="btn primary pin-unlock-btn" type="submit">${icon('check',17)} ${gt('باز کردن حساب‌یار','Unlock Hesabyar')}</button></form><p class="pin-lock-note">${gt('این قفل رابط کاربری است، نه رمزگذاری داده‌ها. اگر PIN را فراموش کنی، بدون پشتیبان ممکن است اطلاعاتت از دست برود.','This PIN locks the interface but does not encrypt your data. Losing the PIN without a backup may mean losing access to your records.')}</p></div></div>`;
 root.querySelector('input[name=pin]')?.focus({preventScroll:true});
}
function engagePinLock(){if(!state.data?.settings?.pinLock||state.locked)return;state.locked=true;pinLockScreen();}
async function unlockPinFromForm(form){if(Date.now()<state.pinBlockedUntil){pinLockScreen('ورود موقتاً محدود شده است؛ کمی بعد دوباره تلاش کن.');return;}
 const pin=value(form,'pin'),ok=await verifyPin(pin);if(!ok){state.pinAttempts++;
 if(state.pinAttempts>=5){state.pinBlockedUntil=Date.now()+Math.min(300000,30000*Math.pow(2,Math.floor((state.pinAttempts-5)/5)));}
 pinLockScreen(state.pinBlockedUntil>Date.now()?'تلاش‌های ناموفق زیاد است. ورود موقتاً محدود شد.':'PIN اشتباه است. دوباره تلاش کن.');return;}
 state.pinAttempts=0;state.pinBlockedUntil=0;state.locked=false;document.body.classList.remove('hy-pin-locked');document.getElementById('pin-lock-root').innerHTML='';
 browserReminder().catch(()=>{});
}

