 <div class="panel theme-panel"><div class="split-title"><div><p class="eyebrow">ظاهر برنامه</p><h3>فضایی که چشم را خسته نکند</h3><p class="panel-sub">۹ تم بازطراحی‌شده؛ با تمرکز بر خوانایی بالا، حس لوکس و تجربه حرفه‌ای</p></div>${icon('theme',22)}</div><div class="theme-grid">${THEME_OPTIONS.map(([id,title,desc])=>`<button type="button" class="theme-option theme-${id} ${state.data.settings.theme===id?'is-selected':''}" data-action="choose-theme" data-theme="${id}" aria-pressed="${state.data.settings.theme===id}"><span class="theme-preview"><span class="preview-sidebar"></span><span class="preview-card big"></span><span class="preview-card one"></span><span class="preview-card two"></span><span class="preview-accent"></span></span><span class="theme-title">${title} ${state.data.settings.theme===id?icon('check',16):''}</span><span class="theme-desc">${desc}</span></button>`).join('')}</div></div>
