function accountModal(id){const a=ws().accounts.find(x=>x.id===id);const referenced=a&&accountUsed(a.id);const body=`<input type="hidden" name="id" value="${a?.id||''}"/><div class="form-grid">${f('نام حساب','name',`<input class="field" name="name" required maxlength="65" placeholder="مثلاً بانک ملت یا کیف پول تتر" value="${esc(a?.name||'')}"/>`,true)}${f('نوع حساب','type',`<select class="select" name="type">${Object.entries(ACCOUNT_TYPES).map(([k,v])=>`<option value="${k}" ${a?.type===k?'selected':''}>${v}</option>`).join('')}</select>`)}${f('ارز حساب','currency',`<select class="select" name="currency" ${referenced?'disabled':''}>${currencyOptions(a?.currency||'IRT')}</select>${referenced?`<input type="hidden" name="currency" value="${a.currency}"/>`:''}`,false,referenced?'ارز حساب دارای گردش مالی قابل تغییر نیست.':'تبدیل ارز خودکار نیست.')}${f('موجودی اولیه','openingBalance',`<input class="field" name="openingBalance" inputmode="decimal" required value="${a?.openingBalance??0}"/>`,true,'موجودی پیش از اولین تراکنشی که در برنامه وارد می‌کنی.')}</div>`;showModal(a?'ویرایش حساب':'افزودن حساب',body,'account-form');}
