function csvExport(){const rows=filterActivities();const cols=(locale()==='en'?['Gregorian date','Jalali date','Time','Type','Category','Contact','Account','Destination account','Source amount','Source currency','Destination amount','Destination currency','Notes']:['تاریخ میلادی','تاریخ شمسی','ساعت','نوع','دسته','طرف حساب','حساب','حساب مقصد','مبلغ مبدأ','ارز مبدأ','مبلغ مقصد','ارز مقصد','توضیحات']);const clean=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};let data=[cols,...rows.map(t=>{const a=findAccount(t.accountId||t.fromAccountId),to=findAccount(t.toAccountId);return[t.date,fmtDate(t.date),t.time||'',typeLabel(t.type),(locale()==='en'?window.HY_I18N?.translate(t.category||''):t.category)||'',t.party||'',t.type==='transfer'?accountName(t.fromAccountId):accountName(t.accountId),to?.name||'',t.amount,a?.currency||'',t.type==='transfer'?t.receivedAmount:'',to?.currency||'',t.note||'']})];download('\ufeff'+data.map(row=>row.map(clean).join(',')).join('\r\n'),`hesabyar-${state.workspace}-${today()}.csv`,'text/csv;charset=utf-8');toast('خروجی CSV آماده شد.')}
async function jsonBackup(){state.data.settings.lastBackup=new Date().toISOString();await persist();const json=JSON.stringify(state.data,null,2);download(json,`hesabyar-full-backup-${today()}.json`,'application/json;charset=utf-8');toast('فایل پشتیبان هر دو دفتر آماده شد. آن را در جایی امن نگهداری کن.');renderShell()}
